function load_buyers(search_txt, selected_buyers, listview) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Customer",
            fields: ["name", "customer_name"],
            limit_page_length: 300,
            filters: { disabled: 0 },
            or_filters: search_txt ? [
                ["Customer", "name", "like", `%${search_txt}%`],
                ["Customer", "customer_name", "like", `%${search_txt}%`]
            ] : []
        },
        callback: function(r) {
            const list = r.message || [];
            let html = '';
            list.forEach(c => {
                const is_selected = selected_buyers.has(c.name) ? 'is-selected' : '';
                html += `
                    <div class="buyer-item ${is_selected}" data-id="${c.name}">
                        <div class="custom-box-phi"></div>
                        <div class="name-stack" style="overflow: hidden;">
                            <div class="buyer-name" title="${c.customer_name || c.name}">${c.customer_name || c.name}</div>
                            <div class="buyer-code">${c.name}</div>
                        </div>
                    </div>
                `;
            });
            $('#buyerList').html(html || '<div class="text-center w-100 p-5 text-muted">Registry Empty</div>');

            $('.buyer-item').on('click', function() {
                const id = $(this).data('id');
                if (selected_buyers.has(id)) {
                    selected_buyers.delete(id);
                    $(this).removeClass('is-selected');
                } else {
                    selected_buyers.add(id);
                    $(this).addClass('is-selected');
                }
                apply_live_filter(listview, [...selected_buyers]);
            });
        }
    });
}

function apply_live_filter(listview, buyers) {
    listview.filter_area.clear();
    if (buyers.length > 0) {
        listview.filter_area.set([[listview.doctype, 'buyer', 'in', buyers]]);
    }
    listview.run();
}

