// ============================================================================
// Order Sheet Entry: Auto Sync + Smart Calculation Engine (PRODUCTION VERSION)
// Composite Key Sync: (size + color)
// ============================================================================

// 1. SYNC TABLE LIST
const SYNC_TABLES = [
    "trim_details",               
    "sewing_thread_booking",      
    "main_label_with_size_details",
    "price_tag_quantity",
    "price_tag_sticker_quantity",
    "hand_tag_details",
    "additional_tag_details",
    "hand_tag_string_details",
    "cartoon_sticker_details",
    "poly_details",
    "blister_details",
    "cartoon_details",
    "gum_tape_details",
    "zipper_booking",
    "button_poly_details",        
    "main_label_details",
    "yarn_details",
    "elastic_details",
    "care_label_with_barcode",    
    "care_label_wo_barcode"       
];

// ============================================================================
// FORM EVENTS
// ============================================================================
frappe.ui.form.on("Order Sheet Entry", {
    refresh(frm) { run_all_calculations(frm); },
    validate(frm) { run_all_calculations(frm); },
    before_save(frm) { run_all_calculations(frm); },
    qty_details_add(frm) { sync_qty_to_tables(frm); },
    qty_details_remove(frm) { sync_qty_to_tables(frm); }
});

frappe.ui.form.on("Order Sheet Qty Detail", {
    qty(frm)     { sync_qty_to_tables(frm); },
    size(frm)    { sync_qty_to_tables(frm); },
    color(frm)  { sync_qty_to_tables(frm); }   // 🔥 color sync
});

// ============================================================================
// CHILD TABLE LISTENERS
// ============================================================================
SYNC_TABLES.forEach(table => {
    frappe.ui.form.on(table, {
        consumption: (frm, cdt, cdn) => run_smart_calc(frm, cdt, cdn),
        wastage:     (frm, cdt, cdn) => run_smart_calc(frm, cdt, cdn),
        quantity:    (frm, cdt, cdn) => run_smart_calc(frm, cdt, cdn)
    });
});

// ============================================================================
// 3. MAIN SYNC ENGINE (SIZE + color)
// ============================================================================
function sync_qty_to_tables(frm) {

    let qty_rows = frm.doc.qty_details || [];

    // composite key = size|color
    let processed_keys = qty_rows
        .filter(r => r.size && r.color)
        .map(r => `${r.size}||${r.color}`);

    SYNC_TABLES.forEach(table_name => {
        if (!frm.get_field(table_name)) return;

        // ---------- AUTO ADD / UPDATE ----------
        qty_rows.forEach(qty_row => {
            if (!qty_row.size || !qty_row.color) return;

            let row = (frm.doc[table_name] || []).find(r =>
                r.size === qty_row.size &&
                r.color === qty_row.color
            );

            if (!row) {
                row = frm.add_child(table_name);
                row.size   = qty_row.size;
                row.color = qty_row.color;   // 🔥 color sync
            }

            // quantity sync
            frappe.model.set_value(
                row.doctype,
                row.name,
                "quantity",
                flt(qty_row.qty)
            );
        });

        // ---------- AUTO REMOVE ----------
        let table_rows = frm.doc[table_name] || [];
        for (let i = table_rows.length - 1; i >= 0; i--) {
            let key = `${table_rows[i].size}||${table_rows[i].color}`;
            if (!processed_keys.includes(key)) {
                table_rows.splice(i, 1);
            }
        }

        frm.refresh_field(table_name);
    });

    run_all_calculations(frm);
}

// ============================================================================
// 4. SMART CALCULATION ENGINE
// ============================================================================
function run_smart_calc(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);

    let qty  = flt(row.quantity);
    let cons = flt(row.consumption);
    let wast = flt(row.wastage);
    let result = 0;

    if (cons > 0 && qty > 0) {

        // Sewing Thread
        if (row.parentfield === "sewing_thread_booking") {
            result = (qty / cons) * (1 + wast / 100);
        } 

        // Button (gross/dozen logic)
        else if (row.parentfield === "trim_details") {
            result = (cons * qty * (1 + wast / 100)) / 1728;
        } 

        // Elastic (gram → lbs)
        else if (row.parentfield === "elastic_details") {
            let grams = (qty * cons) * (1 + wast / 100);
            result = grams / 453.59237; 
        }

        // Other trims / tags / stickers
        else if (row.parentfield !== "yarn_details") {
            result = (qty * cons) * (1 + wast / 100);
        }
    }

    if (row.parentfield !== "yarn_details") {
        frappe.model.set_value(cdt, cdn, "total_trim_required", flt(result, 3));
    }
}

// ============================================================================
// 5. YARN CALCULATION
// ============================================================================
function calculate_yarn_totals(frm) {
    let running_total_lbs = 0;

    (frm.doc.yarn_details || []).forEach(row => {
        let row_grams = (flt(row.consumption) * flt(row.quantity)) * (1 + flt(row.wastage) / 100);
        let row_lbs   = row_grams / 453.59237;

        frappe.model.set_value(row.doctype, row.name, "total_yarn_required", flt(row_lbs, 3));
        running_total_lbs += row_lbs;
    });

    frm.set_value("total_required_yarn", flt(running_total_lbs, 3));
}

// ============================================================================
// 6. FINAL AGGREGATION ENGINE
// ============================================================================
function run_all_calculations(frm) {

    // Sweater Qty
    let total_sweater_qty = (frm.doc.qty_details || [])
        .reduce((sum, r) => sum + flt(r.qty), 0);

    frm.set_value("sweater_quantity", total_sweater_qty);

    // Yarn
    calculate_yarn_totals(frm);

    // Run smart calc on all tables
    SYNC_TABLES.forEach(table => {
        if (frm.doc[table] && table !== "yarn_details") {
            frm.doc[table].forEach(r => run_smart_calc(frm, r.doctype, r.name));
        }
    });

    // Generic total updater
    const update_total = (table, field) => {
        if (!frm.get_field(field)) return;
        let total = (frm.doc[table] || [])
            .reduce((sum, r) => sum + flt(r.total_trim_required), 0);
        frm.set_value(field, flt(total, 3));
    };

    // Existing totals
    update_total('sewing_thread_booking', 'total_sewing_thred_required');
    update_total('trim_details', 'total_button_required');
    update_total('main_label_with_size_details', 'total_main_label_with_size_required');
    update_total('elastic_details', 'total_elastic_required');
    update_total('care_label_with_barcode', 'total_care_label_with_barcode_required');
    update_total('care_label_wo_barcode', 'total_care_label_wo_barcode_required');
    update_total('price_tag_quantity', 'total_price_tag_required');
    update_total('price_tag_sticker_quantity', 'total_price_tag_sticker_required');
    update_total('hand_tag_details', 'total_hand_tag_required');

    // New totals
    update_total('additional_tag_details', 'total_additional_tag_required');
    update_total('hand_tag_string_details', 'total_hand_tag_string_required');
    update_total('cartoon_sticker_details', 'total_cartoon_sticker_required');

    update_total('button_poly_details', 'total_button_poly_required');
    update_total('zipper_booking', 'total_zipper_required');
}

