//   L1  = 1/2 Bottom Gathered             30cm  60N   ← RIB knitting width
//   L2  = Cuff Height                     2.5cm  8R
//   L3  = 1/2 Bottom Before Gathered      35cm  68N   ← CAST ON
//   B1  = Total Length                    39cm 123R
//   C1  = Sleeve Length                   41cm 129R
//   C2  = Armhole Height                  16.4cm 52R
//   C3  = 1/2 Sleeve Opening Gathered     7.4cm  14N  ← CUFF RIB width
//   C5  = Sleeve Cuff Height Gathered     2.5cm   8R
//   C6  = 1/2 Sleeve Opening Bef Gath     10.8cm 22N  ← SLEEVE CAST ON
//   C7  = 1/2 Biceps                      12.4cm 24N
//   C10 = Inside Seam Sleeve Length       30.6cm 96R
//   D1  = Shoulder to Shoulder (full)     → N  (add this row)
//   D2  = Neck Width                      → N  (add this row)
//   D4  = Neck Depth / Front Drop         → R  (add this row)
// ======================================================


// ──────────────────────────────────────────────────────
// CONVERSION  (needles always even)
// ──────────────────────────────────────────────────────

function toNeedle(cm, spi) {
    if (!cm || !spi) return 0;
    return Math.round((parseFloat(cm) / 2.54) * parseFloat(spi) / 2) * 2;
}

function toRow(cm, rpi) {
    if (!cm || !rpi) return 0;
    return Math.round((parseFloat(cm) / 2.54) * parseFloat(rpi));
}


// ──────────────────────────────────────────────────────
// CHILD TABLE HELPERS
// ──────────────────────────────────────────────────────

function getMeasurementRows(frm) {
    let rows = [];
    Object.keys(frm.doc).forEach(key => {
        let v = frm.doc[key];
        if (Array.isArray(v) && v.length > 0 && v[0].doctype === "Sweater Measurement Row")
            rows = v;
    });
    return rows;
}

function getByCode(frm, code) {
    return getMeasurementRows(frm).find(
        r => (r.code || "").trim().toUpperCase() === code.toUpperCase()
    ) || {};
}

// safe getters
function N(row) { return parseFloat(row.needle_value)    || 0; }
function R(row) { return parseFloat(row.row_value)       || 0; }
function CM(row){ return parseFloat(row.pom_measurement) || 0; }
function dv(v)  { return (v !== undefined && v !== null && v !== 0 && v !== "") ? v : "-"; }


// ──────────────────────────────────────────────────────
// FORM EVENTS
// ──────────────────────────────────────────────────────

frappe.ui.form.on('Sweater Technical File', {
    refresh(frm) { calculateAllRows(frm); generateChartPreview(frm); },
    spi(frm)     { calculateAllRows(frm); generateChartPreview(frm); },
    rpi(frm)     { calculateAllRows(frm); generateChartPreview(frm); }
});

frappe.ui.form.on('Sweater Measurement Row', {
    pom_measurement(frm, cdt, cdn) {
        calculateRow(frm, cdt, cdn);
        setTimeout(() => generateChartPreview(frm), 150);
    },
    measurement_type(frm, cdt, cdn) {
        calculateRow(frm, cdt, cdn);
        setTimeout(() => generateChartPreview(frm), 150);
    },
    code(frm) { setTimeout(() => generateChartPreview(frm), 150); }
});


// ──────────────────────────────────────────────────────
// CALCULATE ONE ROW
// ──────────────────────────────────────────────────────

function calculateRow(frm, cdt, cdn) {
    let row  = locals[cdt][cdn];
    let spi  = parseFloat(frm.doc.spi) || 0;
    let rpi  = parseFloat(frm.doc.rpi) || 0;
    let cmv  = parseFloat(row.pom_measurement) || 0;
    let type = (row.measurement_type || "").trim().toLowerCase();

    if (type === "width") {
        frappe.model.set_value(cdt, cdn, "needle_value", toNeedle(cmv, spi));
        frappe.model.set_value(cdt, cdn, "row_value", 0);
    } else if (type === "height") {
        frappe.model.set_value(cdt, cdn, "row_value", toRow(cmv, rpi));
        frappe.model.set_value(cdt, cdn, "needle_value", 0);
    }
}

function calculateAllRows(frm) {
    getMeasurementRows(frm).forEach(row => calculateRow(frm, row.doctype, row.name));
    frm.refresh_fields();
}


// ══════════════════════════════════════════════════════
// SHAPING ENGINE
// Produces the "every R – dec N – × times" notation
// used on meek sweater manual programmer sheets
// Example output: [{ every:2, dec:2, times:1 }, { every:2, dec:1, times:4 }]
// ══════════════════════════════════════════════════════

function shapeSteps(totalN, totalR) {
    // totalN = needles to remove on ONE side
    // totalR = rows available
    if (!totalN || totalN <= 0 || !totalR || totalR <= 0) return [];

    let steps = [];
    let remN  = Math.round(totalN);
    let remR  = Math.round(totalR);

    // Phase 1 — initial fast cast-off block
    if (remN >= 4) {
        let big = Math.min(Math.max(Math.round(remN * 0.3 / 2) * 2, 2), 8);
        steps.push({ every: 2, dec: big, times: 1 });
        remN -= big; remR -= 2;
    }

    // Phase 2 — dec-2 phase
    if (remN >= 4 && remR >= 4) {
        let times    = Math.floor(remN / 2);
        let interval = Math.max(Math.round(remR / (times + 1) / 2) * 2, 2);
        let use      = Math.min(Math.floor(remR / interval), times);
        if (use > 0) {
            steps.push({ every: interval, dec: 2, times: use });
            remN -= use * 2; remR -= use * interval;
        }
    }

    // Phase 3 — single dec finish
    if (remN > 0 && remR >= 2) {
        let interval = Math.max(Math.round(remR / remN / 2) * 2, 2);
        steps.push({ every: interval, dec: 1, times: remN });
    }

    return steps.filter(s => s.times > 0 && s.dec > 0);
}

// Render as coloured badges: "2-2-1"
function badges(steps) {
    if (!steps || !steps.length) return `<span class="badge straight">STRAIGHT</span>`;
    return steps.map(s =>
        `<span class="badge">${s.every}-${s.dec}-${s.times}</span>`
    ).join(" ");
}

// Plain text version for the programmer notation box
function stepsText(steps) {
    if (!steps || !steps.length) return "STRAIGHT";
    return steps.map(s => `${s.every}-${s.dec}-${s.times}`).join("  ");
}


// ══════════════════════════════════════════════════════
// PROGRAMMING CALCULATIONS
// Using your exact data:
//   CAST ON         = L3.N = 68
//   RIB NEEDLES     = L1.N = 60  (after gathering)
//   RIB HEIGHT      = L2.R = 8
//   BODY ROWS       = B1.R - L2.R - C2.R - 6 (shoulder) = 123-8-52-6 = 57
//   ARMHOLE: 68N → shoulder each side over 52R
//   SLEEVE CAST ON  = C6.N = 22
//   SLEEVE CUFF RIB = C3.N = 14, C5.R = 8
//   SLEEVE TAPER    = C3.N(14) → C7.N(24) over C10.R(96)
//   SLEEVE CAP      = C7.N over C2.R
// ══════════════════════════════════════════════════════

function getProgData(frm) {
    let A1  = getByCode(frm, "A1");
    let B1  = getByCode(frm, "B1");
    let C1  = getByCode(frm, "C1");
    let C2  = getByCode(frm, "C2");
    let C3  = getByCode(frm, "C3");
    let C5  = getByCode(frm, "C5");
    let C6  = getByCode(frm, "C6");
    let C7  = getByCode(frm, "C7");
    let C10 = getByCode(frm, "C10");
    let D1  = getByCode(frm, "D1");
    let D2  = getByCode(frm, "D2");
    let D4  = getByCode(frm, "D4");
    let L1  = getByCode(frm, "L1");
    let L2  = getByCode(frm, "L2");
    let L3  = getByCode(frm, "L3");

    // ── BODY ────────────────────────────────────────
    let castOnN    = N(L3);                           // 68N  cast on (before gathered)
    let ribN       = N(L1);                           // 60N  rib needles (after gathered)
    let ribR       = R(L2);                           // 8R   rib rows
    let totalBodyR = R(B1);                           // 123R total length rows
    let ahR        = R(C2);                           // 52R  armhole height
    let shoulderR  = 6;                               // 6R   3 bind-off rows × 2 sides
    let bodyR      = Math.max(totalBodyR - ribR - ahR - shoulderR, 0); // straight body rows
    let chestN     = N(A1);                           // 68N  chest (same as cast on here)

    // shoulder width — use D1 if available, else estimate ~60% of chest×2
    let shoulderFullN = N(D1) || Math.round(chestN * 1.2);
    let shoulderHalfN = Math.round(shoulderFullN / 2);
    let ahReduceN     = Math.max(chestN - shoulderHalfN, 0); // each side

    // neck
    let neckN      = N(D2) || Math.round(chestN * 0.36);     // ~36% of chest
    neckN          = Math.round(neckN / 2) * 2;
    let neckDropR  = R(D4) || Math.round(ahR * 0.4);
    let centerHold = Math.round(neckN * 0.5 / 2) * 2;
    let sideRedN   = Math.max(Math.round((neckN - centerHold) / 2), 0);

    // shoulder slant each side
    let shlN    = Math.max(Math.round((shoulderFullN - neckN) / 2), 0);
    let shlStps = 3;
    let shlPer  = Math.round(shlN / shlStps);
    shlPer      = Math.max(Math.round(shlPer / 2) * 2, 2);
    let shlArr  = [];
    let shlRem  = shlN;
    for (let i = 0; i < shlStps; i++) {
        let take = (i === shlStps - 1) ? shlRem : Math.min(shlPer, shlRem);
        if (take > 0) shlArr.push(take);
        shlRem -= take;
        if (shlRem <= 0) break;
    }

    // ── SLEEVE ──────────────────────────────────────
    let slCastOnN  = N(C6);                           // 22N  before gathered
    let slRibN     = N(C3);                           // 14N  cuff rib (after gathered)
    let slRibR     = R(C5);                           // 8R   cuff rib height
    let slTaperR   = R(C10);                          // 96R  inside seam (taper zone)
    let bicepN     = N(C7);                           // 24N  bicep (× 2 = full 48N)
    let slTotalR   = R(C1);                           // 129R total sleeve
    let slCapR     = R(C2);                           // 52R  cap rows = armhole height

    let slInc      = Math.max(bicepN - slRibN, 0);   // 10N increase each side
    let slEachSide = Math.max(slInc, 0);
    let slInterval = slEachSide > 0
        ? Math.max(Math.round(slTaperR / slEachSide / 2) * 2, 2)
        : 0;

    let slCapN     = Math.round(bicepN * 0.70);       // needles to shape away each side

    return {
        // body
        castOnN, ribN, ribR, bodyR, totalBodyR,
        chestN, ahR, ahReduceN, shoulderHalfN,
        ahSteps:   shapeSteps(ahReduceN, ahR),
        neckN, neckDropR, centerHold, sideRedN,
        neckSteps: shapeSteps(sideRedN, Math.max(neckDropR - 2, 2)),
        shlN, shlArr,
        bodyTotal: ribR + bodyR + ahR + shoulderR,

        // sleeve
        slCastOnN, slRibN, slRibR, slTaperR,
        bicepN, slTotalR, slCapR,
        slInc, slEachSide, slInterval,
        slCapSteps: shapeSteps(slCapN, slCapR),
        slTotal: slRibR + slTaperR + slCapR
    };
}


