        <td>${row.point_of_measure || ""}</td>
        <td>${(row.pom_measurement !== "" && row.pom_measurement !== null && row.pom_measurement !== undefined) ? row.pom_measurement : "-"}</td>
        <td class="nv">${N(row) || "-"}</td>
        <td class="rv">${R(row) || "-"}</td>
    </tr>`).join("");

    return `<table class="mt">
        <thead><tr><th>CODE</th><th>POM</th><th>CM</th><th>N</th><th>R</th></tr></thead>
        <tbody>${body}</tbody>
    </table>`;
}


