frappe.ui.form.on('Daily Production Section', {

    previous_balance(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    production_qty(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    sent_qty(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    },

    reject_qty(frm, cdt, cdn) {
        calculate_row(frm, cdt, cdn);
    }

});

function calculate_row(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    // Running Balance Calculation
    let balance =
        (row.previous_balance || 0)
        + (row.production_qty || 0)
        - (row.sent_qty || 0)
        - (row.reject_qty || 0);

    frappe.model.set_value(
        cdt,
        cdn,
        'running_balance',
        balance
    );

    // Section Efficiency
    if (row.input_qty > 0) {

        let eff =
            ((row.production_qty || 0)
            / row.input_qty) * 100;

        frappe.model.set_value(
            cdt,
            cdn,
            'efficiency',
            eff.toFixed(2)
        );
    }

    calculate_totals(frm);
}

function calculate_totals(frm) {

    let total_output = 0;
    let total_reject = 0;

    (frm.doc.section_entries || []).forEach(row => {

        total_output += row.production_qty || 0;
        total_reject += row.reject_qty || 0;

    });

    // Parent Totals
    frm.set_value(
        'total_output',
        total_output
    );

    frm.set_value(
        'total_reject',
        total_reject
    );

    // Overall Efficiency
    if (frm.doc.target_qty > 0) {

        let overall_eff =
            (total_output / frm.doc.target_qty) * 100;

        frm.set_value(
            'efficiency',
            overall_eff.toFixed(2)
        );
    }
}

// ======================================================
// SWEATER DESIGNER CHART — V19 INDUSTRIAL MASTER
// ERPNext / Frappe Client Script
//
// CHANGELOG V19
// ✔ FIX — chest_shrinkage, length_shrinkage,
//          sleeve_shrinkage, rib_shrinkage
//          all correctly mapped and applied
// ✔ FIX — form events fire on all 4 shrinkage fields
// ✔ FIX — each code maps to its correct shrinkage bucket
// ✔ UPGRADE — industrial-grade programmer output
//             (cast-off + alt-row + 4th-row phases)
// ✔ UPGRADE — sleeve taper excludes rib rows correctly
// ✔ UPGRADE — neck shaping with side decrements
// ✔ UPGRADE — running row counter in programmer tables
// ======================================================



// ======================================================
// SHRINKAGE BUCKET MAP
// ======================================================
//
// chest_shrinkage  → all BODY WIDTH measurements
// length_shrinkage → all HEIGHT / LENGTH measurements
// sleeve_shrinkage → all SLEEVE WIDTH measurements
// rib_shrinkage    → all RIB WIDTH measurements
//
// ┌─────────┬──────────────────────────────────────────┐
// │ BUCKET  │ CODES                                    │
// ├─────────┼──────────────────────────────────────────┤
// │ CHEST   │ A1, D1, D2                               │
// │ LENGTH  │ B1, C1, C2, C5, C10, D4                  │
// │ SLEEVE  │ C6, C7                                   │
// │ RIB     │ L1, L3, C3                               │
// └─────────┴──────────────────────────────────────────┘

const SHRINKAGE_MAP = {
    // CHEST WIDTH — body panel widths
    "A1" : "chest",
    "D1" : "chest",
    "D2" : "chest",

    // HEIGHT / LENGTH — all row-direction measurements
    "B1" : "length",
    "C1" : "length",
    "C2" : "length",
    "C5" : "length",
    "C10": "length",
    "D4" : "length",

    // SLEEVE WIDTH — sleeve panel widths
    "C6" : "sleeve",
    "C7" : "sleeve",

    // RIB WIDTH — all rib / welt bands
    "L1" : "rib",
    "L3" : "rib",
    "C3" : "rib",
};

// Maps bucket name → frm.doc field name
const SHRINKAGE_FIELD = {
    "chest" : "chest_shrinkage",
    "length": "length_shrinkage",
    "sleeve": "sleeve_shrinkage",
    "rib"   : "rib_shrinkage",
};



// ======================================================
// BASIC FUNCTIONS
// ======================================================

function toNeedle(cm, spi) {
    cm  = parseFloat(cm)  || 0;
    spi = parseFloat(spi) || 0;
    if (!cm || !spi) return 0;
    // Always even number — machines work in pairs
    return Math.round(((cm / 2.54) * spi) / 2) * 2;
}

function toRow(cm, rpi) {
    cm  = parseFloat(cm)  || 0;
    rpi = parseFloat(rpi) || 0;
    if (!cm || !rpi) return 0;
    return Math.round((cm / 2.54) * rpi);
}

function applyShrinkage(cm, shrinkagePct) {
    cm           = parseFloat(cm)           || 0;
    shrinkagePct = parseFloat(shrinkagePct) || 0;
    if (!shrinkagePct) return cm;
    // Knitting CM = Finished CM ÷ (1 − shrinkage%)
    return cm / (1 - (shrinkagePct / 100));
}



// ======================================================
// SHRINKAGE ENGINE
// ======================================================

function getShrinkagePct(frm, code) {
    code = (code || "").trim().toUpperCase();
    const bucket = SHRINKAGE_MAP[code];
    if (!bucket) return 0;
    const field  = SHRINKAGE_FIELD[bucket];
    return parseFloat(frm.doc[field]) || 0;
}



// ======================================================
// HELPERS
// ======================================================

function dv(v) {
    return (v !== undefined && v !== null && v !== "" && v !== 0) ? v : "-";
}

function getMeasurementRows(frm) {
    let rows = [];
    Object.keys(frm.doc).forEach(key => {
        let v = frm.doc[key];
        if (Array.isArray(v) && v.length &&
            v[0].doctype === "Sweater Measurement Row") {
            rows = v;
        }
    });
    return rows;
}

function getByCode(frm, code) {
    return getMeasurementRows(frm).find(r =>
        (r.code || "").trim().toUpperCase() === code.toUpperCase()
    ) || {};
}

function N(r)  { return parseFloat(r.needle_value)         || 0; }
function R(r)  { return parseFloat(r.row_value)            || 0; }
function K(r)  { return parseFloat(r.knitting_measurement) || 0; }
function P(r)  { return parseFloat(r.pom_measurement)      || 0; }



// ======================================================
// CALCULATION ENGINE
// ======================================================

function calculateRow(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (!row) return;

    let spi  = parseFloat(frm.doc.spi) || 0;
    let rpi  = parseFloat(frm.doc.rpi) || 0;
    let cm   = parseFloat(row.pom_measurement) || 0;
    let type = (row.measurement_type || "").trim().toLowerCase();
    let code = (row.code || "").trim().toUpperCase();

    // Pull the correct shrinkage % for this measurement code
    let shrinkagePct = getShrinkagePct(frm, code);
    let knittingCM   = parseFloat(
        applyShrinkage(cm, shrinkagePct).toFixed(2)
    );

    row.knitting_measurement = knittingCM;

    if (type === "width") {
        row.needle_value = toNeedle(knittingCM, spi);
        row.row_value    = 0;
    } else if (type === "height") {
        row.row_value    = toRow(knittingCM, rpi);
        row.needle_value = 0;
    }

    // CRITICAL: sync locals[] → frm.doc so chart builders
    // always read the shrinkage-adjusted values
    let docRow = getMeasurementRows(frm).find(r => r.name === cdn);
    if (docRow) {
        docRow.knitting_measurement = row.knitting_measurement;
        docRow.needle_value         = row.needle_value;
        docRow.row_value            = row.row_value;
    }

    refresh_field(row.parentfield);
}

function calculateAllRows(frm) {
    getMeasurementRows(frm).forEach(row => {
        calculateRow(frm, row.doctype, row.name);
    });
    frm.refresh_fields();
}



