// ======================================================
// INDUSTRIAL SHAPING ENGINE
// ======================================================
//
// Standard industrial armhole shaping has 3 phases:
//
//   PHASE 1 — CAST-OFF (bind-off)
//     Large blocks removed in first 1–2 rows.
//     Typically 2–4N cast off at start of each of
//     the first 2 rows (= 1 pass each side).
//
//   PHASE 2 — ALT-ROW DECREMENTS  (every 2R)
//     1N decreased each end every alternate row.
//     This is the main shaping zone. Applied until
//     roughly 60–70% of the reduction is done.
//
//   PHASE 3 — 4TH-ROW DECREMENTS  (every 4R)
//     1N decreased each end every 4th row.
//     Final blending to reach shoulder width.
//
// The split between Phase 2 and Phase 3 is governed
// by the RATIO = totalR / totalN. When the armhole
// is tall relative to the reduction needed, more rows
// are assigned to Phase 3 to spread them out cleanly.
//
// ======================================================

function armholeProgram(totalN, totalR) {
    //
    // totalN = needles to remove PER SIDE
    // totalR = total rows available for armhole
    //
    totalN = Math.abs(Math.round(totalN));
    totalR = Math.abs(Math.round(totalR));

    if (!totalN || !totalR) return { phases: [], usedR: 0 };

    let phases  = [];
    let usedR   = 0;
    let remainN = totalN;
    let remainR = totalR;

    // ── PHASE 1: Cast-off ──────────────────────────
    // Cast off in the first rows. Size depends on reduction.
    // Industry standard: cast off ≥2N, must be ≥1 pass each side.
    let castOffN = 0;
    if (remainN >= 6) {
        castOffN = Math.min(Math.round(remainN * 0.25 / 2) * 2, 4);
        castOffN = Math.max(castOffN, 2);
    } else if (remainN >= 2) {
        castOffN = 2;
    }

    if (castOffN > 0 && castOffN <= remainN) {
        phases.push({
            phase    : 1,
            label    : "CAST OFF",
            every    : 1,       // 1 pass = 1 row per side
            action   : "CAST OFF",
            needles  : castOffN,
            times    : 1,
        });
        remainN -= castOffN;
        remainR -= 2;           // 2 rows consumed (1 each side)
        usedR   += 2;
    }

    // ── PHASE 2: Alt-row decrements (every 2R) ────
    // Assign about 55% of remaining needles to Phase 2
    // (minimum 1, max remainN−1 to leave some for Phase 3)
    let phase2N = 0;
    if (remainN > 1) {
        phase2N = Math.max(
            Math.round(remainN * 0.55),
            1
        );
        // Keep it even if possible for clean pairing
        if (phase2N % 2 !== 0 && phase2N < remainN) {
            phase2N += 1;
        }
        phase2N = Math.min(phase2N, remainN - 1);
    } else {
        phase2N = remainN;
    }

    let phase2R = phase2N * 2;

    if (phase2N > 0 && phase2R <= remainR) {
        phases.push({
            phase    : 2,
            label    : "ALT ROW DEC",
            every    : 2,
            action   : "DEC",
            needles  : 1,
            times    : phase2N,
        });
        remainN -= phase2N;
        remainR -= phase2R;
        usedR   += phase2R;
    }

    // ── PHASE 3: 4th-row decrements ───────────────
    // Spread remaining needles across remaining rows
    // at every 4R interval. If rows don't divide cleanly,
    // recalculate interval to fit.
    if (remainN > 0 && remainR > 0) {
        let interval = Math.max(
            Math.round(remainR / remainN / 2) * 2,
            4
        );
        // Consolidate: if interval is also 2, merge with phase 2
        if (interval === 2 && phases.length > 0 &&
            phases[phases.length - 1].every === 2) {
            phases[phases.length - 1].times += remainN;
        } else {
            phases.push({
                phase    : 3,
                label    : "SPACED DEC",
                every    : interval,
                action   : "DEC",
                needles  : 1,
                times    : remainN,
            });
        }
        usedR += interval * remainN;
    }

    return { phases, usedR };
}


function sleeveProgram(incN, totalR, ribR) {
    //
    // incN   = needles to add PER SIDE  (bicep − cuff) / 2
    // totalR = total sleeve length rows (excl. rib)
    // ribR   = rib rows (excluded from taper zone)
    //
    incN   = Math.abs(Math.round(incN));
    totalR = Math.abs(Math.round(totalR));
    ribR   = Math.abs(Math.round(ribR || 0));

    let taperR = Math.max(totalR - ribR, 0);

    if (!incN || !taperR) return { phases: [], taperR };

    let phases  = [];
    let remainN = incN;
    let remainR = taperR;

    // Industry standard: taper in ONE phase (every Nth row INC)
    // Interval must be even. Consolidate where possible.
    let interval = Math.max(
        Math.round(remainR / remainN / 2) * 2,
        2
    );

    // Check if perfectly even
    let perfectFit = (interval * remainN === remainR);

    if (perfectFit) {
        phases.push({
            phase   : 1,
            label   : "EVEN TAPER",
            every   : interval,
            action  : "INC",
            needles : 1,
            times   : remainN,
        });
    } else {
        // Split into two intervals to use all rows exactly
        let hiInterval = interval + 2;
        let loInterval = interval;
        // loTimes * lo + hiTimes * hi = totalR
        // loTimes + hiTimes = totalN
        // Solve:
        let hiTimes = Math.round(
            (remainR - loInterval * remainN) / (hiInterval - loInterval)
        );
        hiTimes = Math.max(0, Math.min(hiTimes, remainN));
        let loTimes = remainN - hiTimes;

        if (loTimes > 0) {
            phases.push({
                phase   : 1,
                label   : "TAPER",
                every   : loInterval,
                action  : "INC",
                needles : 1,
                times   : loTimes,
            });
        }
        if (hiTimes > 0) {
            phases.push({
                phase   : 2,
                label   : "TAPER",
                every   : hiInterval,
                action  : "INC",
                needles : 1,
                times   : hiTimes,
            });
        }
    }

    return { phases, taperR };
}


function neckProgram(totalN, dropR) {
    //
    // Front neck: knit straight to shoulder depth,
    // divide centre needles, shape each side separately.
    // Standard: cast off centre N, then dec each side
    // every 2R for the remaining drop rows.
    //
    totalN = Math.abs(Math.round(totalN));
    dropR  = Math.abs(Math.round(dropR));

    if (!totalN || !dropR) return { phases: [] };

    let phases = [];

    // Centre cast off (approx 1/3 of neck width)
    let centreN = Math.round(totalN / 3 / 2) * 2;
    centreN = Math.max(centreN, 2);

    let sideN   = Math.round((totalN - centreN) / 2);
    let sideR   = dropR;

    // Decrease each side: 1N every 2R until all gone
    let decTimes = Math.min(sideN, Math.floor(sideR / 2));

    phases.push({
        phase  : 1,
        label  : "CENTRE CAST OFF",
        action : "CAST OFF",
        needles: centreN,
        times  : 1,
        every  : 1,
    });

    if (decTimes > 0) {
        phases.push({
            phase  : 2,
            label  : "SIDE DEC",
            every  : 2,
            action : "DEC",
            needles: 1,
            times  : decTimes,
        });
    }

    // Remaining needles after shaping = shoulder stitches
    let remainEachSide = sideN - decTimes;

    return { phases, centreN, sideN, remainEachSide };
}



// ======================================================
// PROGRAMMER TABLE RENDERER
// ======================================================

function buildProgTable(phases, startRow) {
    if (!phases || !phases.length) {
        return `
        <tr>
            <td colspan="7" class="prog-straight">
                ▬ STRAIGHT — NO SHAPING REQUIRED
            </td>
        </tr>`;
    }

    let runningRow = startRow || 0;
    let totalN = 0;
    let totalR = 0;

    let rows = phases.map((ph, i) => {
        let stepN = ph.needles * ph.times;
        let stepR = ph.every   * ph.times;
        totalN   += stepN;
        totalR   += stepR;

        let rowFrom = runningRow + 1;
        let rowTo   = runningRow + stepR;
        runningRow += stepR;

        let actionClass = ph.action === "DEC"       ? "act-dec"  :
                          ph.action === "INC"       ? "act-inc"  :
                          ph.action === "CAST OFF"  ? "act-cast" : "";

        return `
        <tr>
            <td class="pn">${i + 1}</td>
            <td class="pl">${ph.label}</td>
            <td class="pa ${actionClass}">${ph.action}</td>
            <td class="pv">${ph.needles}<span class="pu">N</span></td>
            <td class="pv">×${ph.times}</td>
            <td class="pv">/ ${ph.every}<span class="pu">R</span></td>
            <td class="pr">R${rowFrom}–R${rowTo}</td>
        </tr>`;
    }).join("");

    return `
        ${rows}
        <tr class="prog-sum">
            <td colspan="2">TOTAL</td>
            <td></td>
            <td class="pv">${totalN}<span class="pu">N</span></td>
            <td></td>
            <td class="pv">${totalR}<span class="pu">R</span></td>
            <td></td>
        </tr>`;
}



