// PROGRAMMER PANEL
// ======================================================

function buildProgrammer(frm) {

    // Pull all relevant codes
    let A1  = getByCode(frm, "A1");   // Chest / body width
    let B1  = getByCode(frm, "B1");   // Body length
    let C1  = getByCode(frm, "C1");   // Sleeve length
    let C2  = getByCode(frm, "C2");   // Armhole depth
    let C3  = getByCode(frm, "C3");   // Cuff rib width
    let C5  = getByCode(frm, "C5");   // Cuff rib height
    let C7  = getByCode(frm, "C7");   // Bicep / sleeve top
    let D1  = getByCode(frm, "D1");   // Shoulder width
    let D2  = getByCode(frm, "D2");   // Neck width
    let D4  = getByCode(frm, "D4");   // Neck drop

    // ── ARMHOLE ────────────────────────────────────
    let chestN    = N(A1);
    let shoulderN = N(D1) || Math.round(chestN * 0.60);
    let armReduceTotal = Math.max(chestN - shoulderN, 0);
    let armReduceSide  = Math.round(armReduceTotal / 2);
    let armholeR       = R(C2);

    let arm = armholeProgram(armReduceSide, armholeR);

    // ── SLEEVE TAPER ───────────────────────────────
    let bicepN  = N(C7);
    let cuffN   = N(C3);
    let tapIncTotal = Math.max(bicepN - cuffN, 0);
    let tapIncSide  = Math.round(tapIncTotal / 2);
    let sleeveR = R(C1);
    let ribR    = R(C5) || 0;

    let slv = sleeveProgram(tapIncSide, sleeveR, ribR);

    // ── NECK ───────────────────────────────────────
    let neckN = N(D2);
    let neckR = R(D4);

    let nk = neckProgram(neckN, neckR);

    // ── SHRINKAGE SUMMARY ──────────────────────────
    let shr = {
        chest : parseFloat(frm.doc.chest_shrinkage)  || 0,
        length: parseFloat(frm.doc.length_shrinkage) || 0,
        sleeve: parseFloat(frm.doc.sleeve_shrinkage) || 0,
        rib   : parseFloat(frm.doc.rib_shrinkage)    || 0,
    };

    return `
    <div class="prog-wrap">

        <!-- ══ SHRINKAGE APPLIED ══════════════════════ -->
        <div class="prog-section">
            <div class="prog-header ph-shr">
                ◈ SHRINKAGE APPLIED
            </div>
            <table class="shr-table">
                <thead>
                    <tr>
                        <th>BUCKET</th>
                        <th>CODES AFFECTED</th>
                        <th>FIELD</th>
                        <th>%</th>
                        <th>FORMULA</th>
                    </tr>
                </thead>
                <tbody>
                    <tr class="${shr.chest  ? '' : 'shr-zero'}">
                        <td class="sb">CHEST</td>
                        <td class="sc">A1, D1, D2</td>
                        <td class="sf">chest_shrinkage</td>
                        <td class="sv">${shr.chest}%</td>
                        <td class="sfm">FIN ÷ (1 − ${shr.chest/100})</td>
                    </tr>
                    <tr class="${shr.length ? '' : 'shr-zero'}">
                        <td class="sb">LENGTH</td>
                        <td class="sc">B1, C1, C2, C5, C10, D4</td>
                        <td class="sf">length_shrinkage</td>
                        <td class="sv">${shr.length}%</td>
                        <td class="sfm">FIN ÷ (1 − ${shr.length/100})</td>
                    </tr>
                    <tr class="${shr.sleeve ? '' : 'shr-zero'}">
                        <td class="sb">SLEEVE</td>
                        <td class="sc">C6, C7</td>
                        <td class="sf">sleeve_shrinkage</td>
                        <td class="sv">${shr.sleeve}%</td>
                        <td class="sfm">FIN ÷ (1 − ${shr.sleeve/100})</td>
                    </tr>
                    <tr class="${shr.rib    ? '' : 'shr-zero'}">
                        <td class="sb">RIB</td>
                        <td class="sc">L1, L3, C3</td>
                        <td class="sf">rib_shrinkage</td>
                        <td class="sv">${shr.rib}%</td>
                        <td class="sfm">FIN ÷ (1 − ${shr.rib/100})</td>
                    </tr>
                </tbody>
            </table>
        </div>


        <!-- ══ ARMHOLE PROGRAM ════════════════════════ -->
        <div class="prog-section">
            <div class="prog-header ph-arm">
                ⬡ ARMHOLE SHAPING PROGRAM
            </div>

            <table class="prog-info-table">
                <tr>
                    <td class="pi-l">CHEST</td>
                    <td class="pi-v">${dv(chestN)}</td>
                    <td class="pi-u">N</td>
                    <td class="pi-l">SHOULDER</td>
                    <td class="pi-v">${dv(shoulderN)}</td>
                    <td class="pi-u">N</td>
                </tr>
                <tr>
                    <td class="pi-l">TOTAL REDUCE</td>
                    <td class="pi-v" style="color:#c00">${dv(armReduceTotal)}</td>
                    <td class="pi-u">N</td>
                    <td class="pi-l">ARMHOLE ROWS</td>
                    <td class="pi-v" style="color:#c00">${dv(armholeR)}</td>
                    <td class="pi-u">R</td>
                </tr>
                <tr>
                    <td class="pi-l">PER SIDE</td>
                    <td class="pi-v" style="color:#1a3a6b">${dv(armReduceSide)}</td>
                    <td class="pi-u">N</td>
                    <td colspan="3" class="pi-note">
                        Apply simultaneously both sides
                    </td>
                </tr>
            </table>

            <table class="prog-steps">
                <thead>
                    <tr>
                        <th>#</th>
                        <th>PHASE</th>
                        <th>ACTION</th>
                        <th>NEEDLES</th>
                        <th>REPS</th>
                        <th>INTERVAL</th>
                        <th>ROWS</th>
                    </tr>
                </thead>
                <tbody>
                    ${buildProgTable(arm.phases, 0)}
                </tbody>
            </table>
        </div>


        <!-- ══ SLEEVE TAPER PROGRAM ═══════════════════ -->
        <div class="prog-section">
            <div class="prog-header ph-slv">
                ◈ SLEEVE TAPER PROGRAM
            </div>

            <table class="prog-info-table">
                <tr>
                    <td class="pi-l">CUFF RIB</td>
                    <td class="pi-v">${dv(cuffN)}</td>
                    <td class="pi-u">N</td>
                    <td class="pi-l">BICEP</td>
                    <td class="pi-v">${dv(bicepN)}</td>
                    <td class="pi-u">N</td>
                </tr>
                <tr>
                    <td class="pi-l">TOTAL INC</td>
                    <td class="pi-v" style="color:#0a8a3c">${dv(tapIncTotal)}</td>
                    <td class="pi-u">N</td>
                    <td class="pi-l">SLEEVE ROWS</td>
                    <td class="pi-v" style="color:#0a8a3c">${dv(sleeveR)}</td>
                    <td class="pi-u">R</td>
                </tr>
                <tr>
                    <td class="pi-l">PER SIDE</td>
                    <td class="pi-v" style="color:#1a3a6b">${dv(tapIncSide)}</td>
                    <td class="pi-u">N</td>
                    <td class="pi-l">RIB ROWS (excl.)</td>
                    <td class="pi-v" style="color:#888">${dv(ribR)}</td>
                    <td class="pi-u">R</td>
                </tr>
                <tr>
                    <td class="pi-l">TAPER ZONE</td>
                    <td class="pi-v" style="color:#1a3a6b">${dv(slv.taperR)}</td>
                    <td class="pi-u">R</td>
                    <td colspan="3" class="pi-note">
                        Increase both ends simultaneously
                    </td>
                </tr>
            </table>

            <table class="prog-steps">
                <thead>
                    <tr>
                        <th>#</th>
                        <th>PHASE</th>
                        <th>ACTION</th>
                        <th>NEEDLES</th>
                        <th>REPS</th>
                        <th>INTERVAL</th>
                        <th>ROWS</th>
                    </tr>
                </thead>
                <tbody>
                    ${buildProgTable(slv.phases, ribR)}
                </tbody>
            </table>
        </div>


        <!-- ══ NECK PROGRAM ═══════════════════════════ -->
        <div class="prog-section">
            <div class="prog-header ph-nk">
                ◯ NECK SHAPING PROGRAM
            </div>

            <table class="prog-info-table">
                <tr>
                    <td class="pi-l">NECK WIDTH</td>
                    <td class="pi-v">${dv(neckN)}</td>
                    <td class="pi-u">N</td>
                    <td class="pi-l">NECK DROP</td>
                    <td class="pi-v">${dv(neckR)}</td>
                    <td class="pi-u">R</td>
                </tr>
                <tr>
                    <td class="pi-l">CENTRE C/O</td>
                    <td class="pi-v" style="color:#c00">${dv(nk.centreN)}</td>
                    <td class="pi-u">N</td>
                    <td class="pi-l">EACH SIDE</td>
                    <td class="pi-v" style="color:#c00">${dv(nk.sideN)}</td>
                    <td class="pi-u">N</td>
                </tr>
                <tr>
                    <td class="pi-l">SHOULDER REM.</td>
                    <td class="pi-v" style="color:#1a3a6b">${dv(nk.remainEachSide)}</td>
                    <td class="pi-u">N/SIDE</td>
                    <td colspan="3" class="pi-note">
                        Shape each side separately after centre cast-off
                    </td>
                </tr>
            </table>

            <table class="prog-steps">
                <thead>
                    <tr>
                        <th>#</th>
                        <th>PHASE</th>
                        <th>ACTION</th>
                        <th>NEEDLES</th>
