function buildGrid() {
    let html = "";
    for (let x = 0; x <= 300; x += 10)
        html += `<line x1="${x}" y1="0" x2="${x}" y2="400" stroke="#e8e8e8" stroke-width="0.4"/>`;
    for (let y = 0; y <= 400; y += 10)
        html += `<line x1="0" y1="${y}" x2="300" y2="${y}" stroke="#e8e8e8" stroke-width="0.4"/>`;
    return html;
}



