function buildMeasurementTable(frm) {
    let rows = getMeasurementRows(frm);

    // Build a shrinkage label for each row
    let html = rows.map(r => {
        let code    = (r.code || "").trim().toUpperCase();
        let bucket  = SHRINKAGE_MAP[code] || "—";
        let shrPct  = getShrinkagePct(frm, code);
        let shrCell = shrPct
            ? `<span class="shr-badge">${bucket.toUpperCase()} ${shrPct}%</span>`
            : `<span class="shr-none">—</span>`;

        return `
        <tr>
            <td><b class="code-tag">${r.code || ""}</b></td>
            <td>${r.point_of_measure || ""}</td>
            <td style="text-align:center;">${dv(P(r))}</td>
            <td style="text-align:center;">${shrCell}</td>
            <td style="text-align:center;color:#c00;font-family:monospace;font-weight:700;">${dv(K(r))}</td>
            <td class="nv">${dv(N(r))}</td>
            <td class="rv">${dv(R(r))}</td>
        </tr>`;
    }).join("");

    return `
    <table class="mt">
        <thead>
            <tr>
                <th>CODE</th>
                <th>POINT OF MEASURE</th>
                <th>FIN. CM</th>
                <th>SHR BUCKET</th>
                <th>KNIT CM</th>
                <th>N</th>
