// ======================================================
// SWEATER DESIGNER CHART — V26
// ERPNext / Frappe Client Script
//
// Based on real factory chart (Meek Sweater & Fashions)
// ✔ Header matches factory format exactly
// ✔ SVG: shapes with N and R labelled on the lines
// ✔ Programmer: SHIMA notation  X-Y-Z  (N-R-Times)
// ✔ Programmer: cumulative needle count after each step
// ✔ ALL-N total shown at bottom of each program
// ✔ All 4 shrinkage buckets correctly applied
// ======================================================


// ======================================================
// SHRINKAGE MAP
// ======================================================

window.SHRINKAGE_MAP = window.SHRINKAGE_MAP || {
    "A1"  : "chest",
    "D1"  : "chest",
    "D2"  : "chest",
    "B1"  : "length",
    "C1"  : "length",
    "C2"  : "length",
    "C5"  : "length",
    "C10" : "length",
    "D4"  : "length",
    "C6"  : "sleeve",
    "C7"  : "sleeve",
    "L1"  : "rib",
    "L2"  : "rib",
    "L3"  : "rib",
    "C3"  : "rib",
};

window.SHRINKAGE_FIELD = window.SHRINKAGE_FIELD || {
    "chest"  : "chest_shrinkage",
    "length" : "length_shrinkage",
    "sleeve" : "sleeve_shrinkage",
    "rib"    : "rib_shrinkage",
};


// ======================================================
// MATH
// ======================================================

function toNeedle(cm, spi) {
    cm = parseFloat(cm) || 0;
    spi = parseFloat(spi) || 0;
    if (!cm || !spi) return 0;
    return Math.round(((cm / 2.54) * spi) / 2) * 2;
}

function toRow(cm, rpi) {
    cm = parseFloat(cm) || 0;
    rpi = parseFloat(rpi) || 0;
    if (!cm || !rpi) return 0;
    return Math.round((cm / 2.54) * rpi);
}

function applyShrinkage(cm, pct) {
    cm = parseFloat(cm) || 0;
    pct = parseFloat(pct) || 0;
    if (!pct) return cm;
    return cm / (1 - pct / 100);
}

function getShrinkagePct(frm, code) {
    code = (code || "").trim().toUpperCase();
    const bucket = window.SHRINKAGE_MAP[code];
    if (!bucket) return 0;
    return parseFloat(frm.doc[window.SHRINKAGE_FIELD[bucket]]) || 0;
}


// ======================================================
// HELPERS
// ======================================================

function dv(v) {
    return (v !== undefined && v !== null && v !== "" && v !== 0) ? v : "-";
}
function N(r)  { return parseFloat(r.needle_value)         || 0; }
function R(r)  { return parseFloat(r.row_value)            || 0; }
function K(r)  { return parseFloat(r.knitting_measurement) || parseFloat(r.pom_measurement) || 0; }
function P(r)  { return parseFloat(r.pom_measurement)      || 0; }
function f1(v) { // format to 1dp or integer
    let n = parseFloat(v);
    if (!n) return "-";
    return Number.isInteger(n) ? String(n) : n.toFixed(1);
}


// ======================================================
// ROW ACCESS
// ======================================================

function getMeasurementRows(frm) {
    let rows = [];
    Object.keys(frm.doc).forEach(key => {
        let val = frm.doc[key];
        if (Array.isArray(val) && val.length &&
            val[0].doctype === "Sweater Measurement Row") rows = val;
    });
    return rows;
}

function getByCode(frm, code) {
    return getMeasurementRows(frm).find(r =>
        (r.code || "").trim().toUpperCase() === code.toUpperCase()
    ) || {};
}


// ======================================================
// CALCULATION ENGINE
// ======================================================

function calculateRow(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (!row) return;

    let spi  = parseFloat(frm.doc.spi) || 0;
    let rpi  = parseFloat(frm.doc.rpi) || 0;
    let cm   = parseFloat(row.pom_measurement) || 0;
    let type = (row.measurement_type || "").trim().toLowerCase();
    let code = (row.code || "").trim().toUpperCase();

    let pct        = getShrinkagePct(frm, code);
    let knittingCM = parseFloat(applyShrinkage(cm, pct).toFixed(2));
    row.knitting_measurement = knittingCM;

    if (type === "width")  { row.needle_value = toNeedle(knittingCM, spi); row.row_value    = 0; }
    if (type === "height") { row.row_value    = toRow(knittingCM, rpi);    row.needle_value = 0; }

    if (["L1","L3","C3"].includes(code)) row.needle_value = toNeedle(knittingCM, spi);
    if (["L2","C5"].includes(code))      row.row_value    = toRow(knittingCM, rpi);

    let docRow = getMeasurementRows(frm).find(r => r.name === cdn);
    if (docRow) {
        docRow.knitting_measurement = row.knitting_measurement;
        docRow.needle_value         = row.needle_value;
        docRow.row_value            = row.row_value;
    }
    refresh_field(row.parentfield);
}

function calculateAllRows(frm) {
    getMeasurementRows(frm).forEach(row => calculateRow(frm, row.doctype, row.name));
    frm.refresh_fields();
}


