    chest_shrinkage(frm)   { calculateAllRows(frm); generateChartPreview(frm); },
    length_shrinkage(frm)  { calculateAllRows(frm); generateChartPreview(frm); },
    sleeve_shrinkage(frm)  { calculateAllRows(frm); generateChartPreview(frm); },
