    measurement_type(frm, cdt, cdn) { calculateRow(frm, cdt, cdn); generateChartPreview(frm); },
    code(frm, cdt, cdn)             { calculateRow(frm, cdt, cdn); generateChartPreview(frm); },
});


// ======================================================
// SHAPING ENGINE — SHIMA / FACTORY NOTATION
// ======================================================
//
// Output: array of steps, each step = { n, r, t }
//   n = needles per decrease/increase
//   r = row interval
//   t = times repeated
//
// Factory notation on chart: N-R-T
//   e.g.  2-2-3  means: decrease 2N every 2R, 3 times
//         1-2-8  means: decrease 1N every 2R, 8 times
//
// Cumulative needle count is shown after EACH step.

function calcShaping(startN, endN, totalR, dir) {
    // dir = "dec" or "inc"
    let totalNchange = Math.abs(Math.round(startN - endN));
    totalR = Math.abs(Math.round(totalR));
    if (!totalNchange || !totalR) return [];

    let steps   = [];
    let remN    = totalNchange;
    let remR    = totalR;

    if (dir === "dec") {
        // Step 1 — initial bind-off block (cast off several N at once)
        // Only if reduction is significant (≥6 each side)
        if (remN >= 6) {
            let coN = Math.min(Math.round(remN * 0.20 / 2) * 2, 4);
            coN = Math.max(coN, 2);
            // This is done in 1 row pass per side (so uses 2 rows)
            steps.push({ n: coN, r: 1, t: 1, type: "castoff" });
            remN -= coN;
            remR -= 2;
        }

        // Step 2 — every 2 rows (alt row) — main shaping
        // Assign ~60% of remaining needles to alt-row phase
        if (remN > 1 && remR >= 4) {
            let altN = Math.round(remN * 0.60 / 2) * 2;
            altN = Math.max(2, Math.min(altN, remN - 1));
            // Must be doable: altN times * 2 rows <= remR
            while (altN * 2 > remR - 2 && altN > 0) altN -= 2;
            if (altN > 0) {
                steps.push({ n: 1, r: 2, t: altN, type: "dec" });
                remN -= altN;
                remR -= altN * 2;
            }
        }

        // Step 3 — remaining: spread over remaining rows
        if (remN > 0 && remR > 0) {
            let iv = Math.max(Math.round(remR / remN / 2) * 2, 2);
            steps.push({ n: 1, r: iv, t: remN, type: "dec" });
        }
    }

    if (dir === "inc") {
        // Sleeve taper — increase 1N each side at intervals
        // Split into two groups if rows don't divide evenly
        let iv  = Math.max(Math.round(remR / remN / 2) * 2, 2);
        let hi  = iv + 2;
        // Solve: loT*iv + hiT*hi = totalR,  loT + hiT = totalNchange
        let hiT = Math.round((remR - iv * remN) / (hi - iv));
        hiT = Math.max(0, Math.min(hiT, remN));
        let loT = remN - hiT;
        if (loT > 0) steps.push({ n: 1, r: iv, t: loT, type: "inc" });
        if (hiT > 0) steps.push({ n: 1, r: hi, t: hiT, type: "inc" });
    }

    return steps;
}


// ======================================================
// PROGRAMMER TABLE RENDERER — SHIMA FORMAT
// ======================================================
//
// Each row shows:
//   STEP  |  N-R-T notation  |  What it means plain English  |  Cumulative N after step
//
// Example rows:
//   1  |  4-1-1  |  Cast off 4N (once each side)      |  243 NC
//   2  |  1-2-8  |  Dec 1N every 2R × 8 times         |  227 NC
//   3  |  1-4-3  |  Dec 1N every 4R × 3 times         |  221 NC
//      |         |  ALL = 207N                          |

function buildShimaTable(steps, startN, label) {
    if (!steps.length) {
        return `<div class="sh-straight">STRAIGHT — NO SHAPING</div>`;
    }

    let cumN = startN;
    let rows = steps.map((s, i) => {
        let totalNthisStep = s.n * s.t * 2; // both sides
        cumN -= (s.type === "inc" ? -totalNthisStep : totalNthisStep);
        let notation   = `${s.n}-${s.r}-${s.t}`;
        let plain;
        if (s.type === "castoff") {
            plain = `Cast off ${s.n}N each side (once)`;
        } else if (s.type === "dec") {
            plain = `Dec ${s.n}N each side, every ${s.r} rows × ${s.t}`;
        } else {
            plain = `Inc ${s.n}N each side, every ${s.r} rows × ${s.t}`;
        }
        let rowsUsed = s.r * s.t;
        return `<tr>
            <td class="sh-step">${i + 1}</td>
            <td class="sh-nrt">${notation}</td>
            <td class="sh-plain">${plain}</td>
            <td class="sh-rows">${rowsUsed}R</td>
            <td class="sh-cum">${cumN} N</td>
        </tr>`;
    }).join("");

    let totalNreduced = steps.reduce((a, s) => a + s.n * s.t * 2, 0);
    let totalRused    = steps.reduce((a, s) => a + s.r * s.t, 0);
    let finalN        = steps[0].type === "inc"
        ? startN + totalNreduced
        : startN - totalNreduced;

    return `
    <table class="sh-table">
        <thead>
            <tr>
                <th>#</th>
                <th>N–R–T</th>
                <th>INSTRUCTION</th>
                <th>ROWS</th>
                <th>NEEDLE COUNT</th>
            </tr>
        </thead>
        <tbody>
            <tr class="sh-start">
                <td></td>
                <td>START</td>
                <td>${label} — start needles</td>
                <td></td>
                <td>${startN} N</td>
            </tr>
            ${rows}
        </tbody>
        <tfoot>
            <tr class="sh-all">
                <td colspan="3">ALL = ${finalN} N &nbsp;|&nbsp; ROWS USED = ${totalRused} R</td>
                <td>${totalRused}R</td>
                <td>${finalN} N</td>
            </tr>
        </tfoot>
    </table>`;
}


