// ======================================================
// SVG HELPERS
// ======================================================
// Simple, clean — label lines ON the shape edges

// Text label on a horizontal line of the shape
function hl(x1, x2, y, topLabel, botLabel) {
    let mx = (x1 + x2) / 2;
    return `
    <text x="${mx}" y="${y - 5}" text-anchor="middle"
        font-family="Courier New" font-size="9" font-weight="700" fill="#111">${topLabel}</text>
    ${botLabel ? `<text x="${mx}" y="${y + 12}" text-anchor="middle"
        font-family="Courier New" font-size="8" fill="#444">${botLabel}</text>` : ""}`;
}

// Text label on a vertical edge
function vl(x, y1, y2, label, side) {
    // side: "left" or "right"
    let my = (y1 + y2) / 2;
    let tx = side === "left" ? x - 8 : x + 8;
    let anchor = side === "left" ? "end" : "start";
    return `
    <text x="${tx}" y="${my + 4}" text-anchor="${anchor}"
        font-family="Courier New" font-size="9" font-weight="700" fill="#111"
        transform="rotate(${side === "left" ? -90 : 90},${tx},${my + 4})">${label}</text>`;
}

// Dimension arrow line (horizontal)
function dimH(x1, x2, y, label) {
    let mx = (x1 + x2) / 2;
    return `
    <line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="#333" stroke-width="0.8"/>
    <line x1="${x1}" y1="${y-4}" x2="${x1}" y2="${y+4}" stroke="#333" stroke-width="0.8"/>
    <line x1="${x2}" y1="${y-4}" x2="${x2}" y2="${y+4}" stroke="#333" stroke-width="0.8"/>
    <text x="${mx}" y="${y - 5}" text-anchor="middle"
        font-family="Courier New" font-size="8.5" font-weight="700" fill="#111">${label}</text>`;
}

// Dimension arrow line (vertical)
function dimV(x, y1, y2, label) {
    let my = (y1 + y2) / 2;
    return `
    <line x1="${x}" y1="${y1}" x2="${x}" y2="${y2}" stroke="#333" stroke-width="0.8"/>
    <line x1="${x-4}" y1="${y1}" x2="${x+4}" y2="${y1}" stroke="#333" stroke-width="0.8"/>
    <line x1="${x-4}" y1="${y2}" x2="${x+4}" y2="${y2}" stroke="#333" stroke-width="0.8"/>
    <text x="${x + 10}" y="${my + 3}" text-anchor="middle"
        font-family="Courier New" font-size="8.5" font-weight="700" fill="#111"
        transform="rotate(90, ${x + 10}, ${my + 3})">${label}</text>`;
}


