// ======================================================
// PROGRAMMER — SHIMA FORMAT
// ======================================================

function buildPrograms(frm) {
    let A1 = getByCode(frm, "A1");
    let B1 = getByCode(frm, "B1");
    let C1 = getByCode(frm, "C1");
    let C2 = getByCode(frm, "C2");
    let C3 = getByCode(frm, "C3");
    let C5 = getByCode(frm, "C5");
    let C7 = getByCode(frm, "C7");
    let D1 = getByCode(frm, "D1");
    let D2 = getByCode(frm, "D2");
    let D4 = getByCode(frm, "D4");
    let L1 = getByCode(frm, "L1");
    let L2 = getByCode(frm, "L2");

    let chestN    = N(A1);
    let shoulderN = N(D1) || Math.round(chestN * 0.60);
    let armSteps  = calcShaping(chestN, shoulderN, R(C2), "dec");

    let bicepN    = N(C7);
    let cuffN     = N(C3);
    let taperR    = Math.max(R(C1) - R(C5), 0);
    let tapSteps  = calcShaping(cuffN, bicepN, taperR, "inc");

    let neckN     = N(D2);
    let centreN   = Math.round(neckN / 3 / 2) * 2;
    let sideN     = Math.round((neckN - centreN) / 2);
    let neckSteps = calcShaping(sideN, 0, R(D4), "dec");

    function block(num, title, info, table) {
        return `<div class="pg-block">
            <div class="pg-title">${num}. ${title}</div>
            <div class="pg-info">${info}</div>
            ${table}
        </div>`;
    }

    // Body knitting sequence (plain text steps)
    let bodySeq = `
    <div class="pg-block">
        <div class="pg-title">1. BODY KNITTING SEQUENCE</div>
        <table class="pg-seq-tbl">
            <tr><td class="sq-n">1</td><td>Cast on <b>${dv(N(L1))}</b> N &nbsp;→&nbsp; Knit rib <b>${dv(R(L2))}</b> R &nbsp;<em>(L1=${dv(N(L1))}N, L2=${dv(R(L2))}R, knit ${f1(K(L1))}cm)</em></td></tr>
            <tr><td class="sq-n">2</td><td>Change cam to body tension</td></tr>
            <tr><td class="sq-n">3</td><td>Expand to <b>${dv(N(A1))}</b> N &nbsp;→&nbsp; Knit body <b>${dv(R(B1))}</b> R &nbsp;<em>(A1=${f1(K(A1))}cm, B1=${f1(K(B1))}cm)</em></td></tr>
            <tr><td class="sq-n">4</td><td>Begin armhole shaping — see program 2</td></tr>
        </table>
    </div>`;

    let armInfo = `CHEST = ${dv(chestN)}N &nbsp;→&nbsp; SHOULDER = ${dv(shoulderN)}N &nbsp;|&nbsp;
        REDUCE = ${dv(chestN - shoulderN)}N total &nbsp;(${dv(Math.round((chestN - shoulderN)/2))}N per side) &nbsp;|&nbsp;
        ARMHOLE HEIGHT = ${dv(R(C2))}R`;

    let tapInfo = `CUFF = ${dv(cuffN)}N &nbsp;→&nbsp; BICEP = ${dv(bicepN)}N &nbsp;|&nbsp;
        INCREASE = ${dv(bicepN - cuffN)}N total &nbsp;(${dv(Math.round((bicepN - cuffN)/2))}N per side) &nbsp;|&nbsp;
        TAPER ROWS = ${dv(taperR)}R &nbsp;(total sleeve ${dv(R(C1))}R minus cuff rib ${dv(R(C5))}R)`;

    let nkInfo = `NECK WIDTH = ${dv(neckN)}N &nbsp;|&nbsp; CENTRE CAST OFF = ${dv(centreN)}N &nbsp;|&nbsp;
        EACH SIDE = ${dv(sideN)}N &nbsp;|&nbsp; NECK DROP = ${dv(R(D4))}R`;

    return `<div class="prog-wrap">
        ${bodySeq}
        ${block("2", "ARMHOLE SHAPING &nbsp; [ N–R–T = Needles–RowInterval–Times, EACH SIDE ]",
            armInfo, buildShimaTable(armSteps, chestN, "CHEST"))}
        ${block("3", "SLEEVE TAPER &nbsp; [ N–R–T = Needles–RowInterval–Times, EACH SIDE ]",
            tapInfo, buildShimaTable(tapSteps, cuffN, "CUFF"))}
        ${block("4", "NECK SHAPING &nbsp; [ N–R–T = Needles–RowInterval–Times, EACH SIDE ]",
            nkInfo, buildShimaTable(neckSteps, sideN, "EACH SIDE"))}
    </div>`;
}


