// ======================================================
// SWEATER DESIGNER CHART — V27
// ERPNext / Frappe Client Script
//
// REAL SCENARIO (from factory charts):
//
// The user provided:  RPC = 2.42,  NPC = 3.94
// These are ROWS PER CM and NEEDLES PER CM.
// The gauge unit field (gauge_unit) must be "per_cm" or "per_inch".
//
// CONVERSION:
//   If gauge is PER INCH (traditional SPI/RPI):
//     needles = (cm / 2.54) × SPI   → rounded to even
//     rows    = (cm / 2.54) × RPI
//
//   If gauge is PER CM (NPC / RPC):
//     needles = cm × NPC            → rounded to even
//     rows    = cm × RPC
//
// EXAMPLE with real data (size M, chest = 59cm finish):
//   NPC = 3.94,  chest shrinkage = 0%
//   knit_cm = 59 cm
//   needles = 59 × 3.94 = 232.46 → 232N  (matches ~209N at half-chest)
//   half-chest knit = 59/2 = 29.5 × 3.94 = 116N each side → 232N total ✓
//
// SHIMA PROGRAMMER NOTATION:
//   N-R-T  =  Needles to change − Row interval − Times repeated
//   e.g.  2-2-1  = cast off/dec 2N, every 2 rows, 1 time
//         1-2-8  = dec 1N each side, every 2 rows, 8 times
//   ALL = final needle count after all steps
//   Cumulative (NC) shown after every step
//
// ======================================================


// ======================================================
// SHRINKAGE MAP
// ======================================================

window.SHRINKAGE_MAP = window.SHRINKAGE_MAP || {
    "A1"  : "chest",   // Chest / body width
    "D1"  : "chest",   // Shoulder width
    "D2"  : "chest",   // Neck width
    "B1"  : "length",  // Body length
    "C1"  : "length",  // Sleeve length
    "C2"  : "length",  // Armhole depth
    "C5"  : "length",  // Cuff rib height
    "C10" : "length",  // Inside sleeve
    "D4"  : "length",  // Neck drop
    "C6"  : "sleeve",  // Sleeve opening (at underarm)
    "C7"  : "sleeve",  // Bicep / sleeve top width
    "L1"  : "rib",     // Bottom rib width
    "L2"  : "rib",     // Bottom rib height
    "L3"  : "rib",     // Additional rib
    "C3"  : "rib",     // Cuff rib width
};

window.SHRINKAGE_FIELD = window.SHRINKAGE_FIELD || {
    "chest"  : "chest_shrinkage",
    "length" : "length_shrinkage",
    "sleeve" : "sleeve_shrinkage",
    "rib"    : "rib_shrinkage",
};


// ======================================================
// GAUGE UNIT DETECTION
// Returns "cm" if gauge is entered as per-cm (NPC/RPC)
// Returns "inch" if gauge is entered as per-inch (SPI/RPI)
// Field on doctype: gauge_unit  ("per_cm" | "per_inch")
// ======================================================

function getGaugeUnit(frm) {
    return (frm.doc.gauge_unit || "per_inch").toLowerCase();
}


// ======================================================
// CORE CONVERSION — handles BOTH gauge units
// ======================================================

function toNeedle(cm, spi_or_npc, unit) {
    cm          = parseFloat(cm)          || 0;
    spi_or_npc  = parseFloat(spi_or_npc) || 0;
    if (!cm || !spi_or_npc) return 0;

    let raw;
    if (unit === "per_cm") {
        // NPC = needles per cm
        raw = cm * spi_or_npc;
    } else {
        // SPI = stitches per inch  →  convert cm→inch first
        raw = (cm / 2.54) * spi_or_npc;
    }
    // Always round to nearest EVEN number (machine works in pairs)
    return Math.round(raw / 2) * 2;
}

function toRow(cm, rpi_or_rpc, unit) {
    cm          = parseFloat(cm)          || 0;
    rpi_or_rpc  = parseFloat(rpi_or_rpc) || 0;
    if (!cm || !rpi_or_rpc) return 0;

    if (unit === "per_cm") {
        return Math.round(cm * rpi_or_rpc);
    } else {
        return Math.round((cm / 2.54) * rpi_or_rpc);
    }
}

function applyShrinkage(cm, pct) {
    cm  = parseFloat(cm)  || 0;
    pct = parseFloat(pct) || 0;
    if (!pct) return cm;
    return cm / (1 - pct / 100);
}

function getShrinkagePct(frm, code) {
    code = (code || "").trim().toUpperCase();
    const bucket = window.SHRINKAGE_MAP[code];
    if (!bucket) return 0;
    return parseFloat(frm.doc[window.SHRINKAGE_FIELD[bucket]]) || 0;
}


// ======================================================
// HELPERS
// ======================================================

function dv(v) {
    return (v !== undefined && v !== null && v !== "" && v !== 0) ? v : "-";
}
function N(r)  { return parseFloat(r.needle_value)          || 0; }
function R(r)  { return parseFloat(r.row_value)             || 0; }
function K(r)  { return parseFloat(r.knitting_measurement)  || parseFloat(r.pom_measurement) || 0; }
function P(r)  { return parseFloat(r.pom_measurement)       || 0; }

function f1(v) {
    let n = parseFloat(v);
    if (!n) return "-";
    return Number.isInteger(n) ? String(n) : n.toFixed(1);
}

function f2(v) {
    let n = parseFloat(v);
    if (!n) return "-";
    return n.toFixed(2);
}


// ======================================================
// ROW ACCESS
// ======================================================

function getMeasurementRows(frm) {
    let rows = [];
    Object.keys(frm.doc).forEach(key => {
        let val = frm.doc[key];
        if (Array.isArray(val) && val.length &&
            val[0].doctype === "Sweater Measurement Row") rows = val;
    });
    return rows;
}

function getByCode(frm, code) {
    return getMeasurementRows(frm).find(r =>
        (r.code || "").trim().toUpperCase() === code.toUpperCase()
    ) || {};
}


// ======================================================
// CALCULATION ENGINE
// ======================================================

function calculateRow(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (!row) return;

    let unit = getGaugeUnit(frm);
    let spi  = parseFloat(frm.doc.spi) || 0;  // stitches per inch OR per cm
    let rpi  = parseFloat(frm.doc.rpi) || 0;  // rows per inch OR per cm
    let cm   = parseFloat(row.pom_measurement) || 0;
    let type = (row.measurement_type || "").trim().toLowerCase();
    let code = (row.code || "").trim().toUpperCase();

    // Apply shrinkage to get knitting cm
    let pct        = getShrinkagePct(frm, code);
    let knittingCM = parseFloat(applyShrinkage(cm, pct).toFixed(2));
    row.knitting_measurement = knittingCM;

    // Calculate needle / row value
    if (type === "width") {
        row.needle_value = toNeedle(knittingCM, spi, unit);
        row.row_value    = 0;
    }
    if (type === "height") {
        row.row_value    = toRow(knittingCM, rpi, unit);
        row.needle_value = 0;
    }

    // Rib codes always need needle calc (width)
    if (["L1","L3","C3"].includes(code)) {
        row.needle_value = toNeedle(knittingCM, spi, unit);
    }
    // Rib height codes
    if (["L2","C5"].includes(code)) {
        row.row_value = toRow(knittingCM, rpi, unit);
    }

    // Sync locals → frm.doc
    let docRow = getMeasurementRows(frm).find(r => r.name === cdn);
    if (docRow) {
        docRow.knitting_measurement = row.knitting_measurement;
        docRow.needle_value         = row.needle_value;
        docRow.row_value            = row.row_value;
    }
    refresh_field(row.parentfield);
}

function calculateAllRows(frm) {
    getMeasurementRows(frm).forEach(row =>
        calculateRow(frm, row.doctype, row.name)
    );
    frm.refresh_fields();
}


