// ======================================================
// SHAPING ENGINE  — produces SHIMA N-R-T steps
// ======================================================
//
// calcShaping(startN, endN, totalR, dir)
//
// startN = needle count at start of shaping zone
// endN   = needle count at end of shaping zone
// totalR = total rows available for this shaping zone
// dir    = "dec" (decrease) | "inc" (increase)
//
// Returns array of steps:
//   { n, r, t, type }
//   n    = needles changed per operation (each side)
//   r    = row interval
//   t    = times repeated
//   type = "castoff" | "dec" | "inc"
//
// Factory N-R-T interpretation:
//   n-r-t means: change n needles, every r rows, t times
//   Total needles changed = n × t × 2 (both sides)
//   Total rows used       = r × t
//
// ALL = startN − total_reduction  (or + total_increase)

function calcShaping(startN, endN, totalR, dir) {
    let totalNchange = Math.abs(Math.round(startN - endN));
    totalR = Math.abs(Math.round(totalR));

    if (!totalNchange || !totalR) return [];

    let steps = [];
    let remN  = totalNchange;   // remaining needles to distribute
    let remR  = totalR;         // remaining rows to use

    // ── DECREASE ─────────────────────────────────────
    if (dir === "dec") {

        // PHASE 1 — Initial cast-off
        // Typical factory practice: cast off 2–4N each side
        // in the very first pass (1 row pass = 2 rows consumed,
        // one for each side). Only done if reduction is ≥ 4N each side.
        let halfN = Math.round(totalNchange / 2); // per side
        if (halfN >= 4 && remR >= 2) {
            // Cast off 2N each side (standard armhole opening)
            let coN = 2;
            // Use 2N-1R-1 notation: 2 needles, 1 row pass, 1 time
            steps.push({ n: coN, r: 1, t: 1, type: "castoff" });
            remN -= coN * 2;  // both sides
            remR -= 2;
        }

        // PHASE 2 — Alt-row decrements (every 2 rows)
        // Main shaping: 1N dec each side every 2R
        // Assign as many as possible up to ~65% of remaining
        if (remN > 0 && remR >= 4) {
            let maxAlt = Math.floor(remR / 2);         // max possible
            let wantAlt = Math.round(remN * 0.65 / 2) * 2; // ~65%, even
            let altTimes = Math.min(
                Math.floor(remN / 2),   // can't exceed half remN (1N per side per step)
                Math.min(maxAlt, Math.max(wantAlt / 1, 1))
            );
            // altTimes here is PER SIDE already (n=1 each side)
            // cap to what rows allow
            altTimes = Math.min(altTimes, Math.floor((remR - 2) / 2));
            altTimes = Math.max(altTimes, 0);

            if (altTimes > 0) {
                steps.push({ n: 1, r: 2, t: altTimes, type: "dec" });
                remN -= altTimes * 2;  // 1N × altTimes × 2 sides
                remR -= altTimes * 2;
            }
        }

        // PHASE 3 — Spaced decrements (every 4R or more)
        // Remainder: spread over remaining rows
        if (remN > 0 && remR > 0) {
            // remN is total (both sides), so per-side = remN/2
            let perSide = Math.max(1, Math.round(remN / 2));
            let iv = Math.max(
                Math.round(remR / perSide / 2) * 2,
                2
            );
            // Consolidate: if same interval as phase 2, merge
            let last = steps[steps.length - 1];
            if (last && last.r === iv && last.type === "dec") {
                last.t += perSide;
                // remN, remR already consumed in push logic
            } else {
                steps.push({ n: 1, r: iv, t: perSide, type: "dec" });
            }
        }
    }

    // ── INCREASE ─────────────────────────────────────
    if (dir === "inc") {
        // Sleeve taper: inc 1N each side at even intervals
        // Per side increase = totalNchange / 2
        let perSide = Math.max(1, Math.round(totalNchange / 2));

        // Base interval
        let iv = Math.max(
            Math.round(totalR / perSide / 2) * 2,
            2
        );

        // Check if it divides cleanly
        let rowsNeeded = iv * perSide;
        let rowsDiff   = totalR - rowsNeeded;

        if (rowsDiff === 0) {
            // Perfect fit
            steps.push({ n: 1, r: iv, t: perSide, type: "inc" });
        } else {
            // Split into two intervals to consume all rows exactly
            // loT steps at iv,  hiT steps at (iv+2)
            let hi  = iv + 2;
            let hiT = Math.round(rowsDiff / 2);
            hiT = Math.max(0, Math.min(hiT, perSide));
            let loT = perSide - hiT;
            if (loT > 0) steps.push({ n: 1, r: iv,  t: loT, type: "inc" });
            if (hiT > 0) steps.push({ n: 1, r: hi,  t: hiT, type: "inc" });
        }
    }

    return steps;
}


// ======================================================
// SHIMA PROGRAMMER TABLE
// ======================================================
//
// Renders the N-R-T steps in a table exactly like the
// hand-written factory programmer boxes in the chart photo:
//
//   START:  [startN] N
//   1       2-1-1    Cast off 2N each side ×1        [cumN] NC
//   2       1-2-8    Dec 1N each side / 2R ×8        [cumN] NC
//   3       1-4-3    Dec 1N each side / 4R ×3        [cumN] NC
//           ALL = [finalN] N

function shimaTable(steps, startN, dir) {
    if (!steps.length) {
        return `<div class="sh-none">STRAIGHT — NO SHAPING</div>`;
    }

    let cumN = startN;

    let bodyRows = steps.map((s, i) => {
        // Both sides
        let deltaPerStep = s.n * s.t * 2;
        if (dir === "inc" || s.type === "inc") {
            cumN += deltaPerStep;
        } else {
            cumN -= deltaPerStep;
        }

        let nrt = `${s.n}-${s.r}-${s.t}`;

        let desc;
        if (s.type === "castoff") {
            desc = `Cast off ${s.n}N each side  (${s.t} pass)`;
        } else if (s.type === "dec") {
            desc = `Dec ${s.n}N each end  /  ${s.r}R  ×${s.t}`;
        } else {
            desc = `Inc ${s.n}N each end  /  ${s.r}R  ×${s.t}`;
        }

        let rowsUsed = s.r * s.t;

        return `<tr>
            <td class="st-i">${i + 1}</td>
            <td class="st-nrt">${nrt}</td>
            <td class="st-desc">${desc}</td>
            <td class="st-ru">${rowsUsed}R</td>
            <td class="st-nc">${cumN} NC</td>
        </tr>`;
    }).join("");

    let totalNchanged = steps.reduce((a, s) => a + s.n * s.t * 2, 0);
    let totalRused    = steps.reduce((a, s) => a + s.r * s.t,     0);
    let finalN        = (dir === "inc")
        ? startN + totalNchanged
        : startN - totalNchanged;

    return `
    <table class="sh-tbl">
        <thead>
            <tr>
                <th>#</th>
                <th>N-R-T</th>
                <th>INSTRUCTION</th>
                <th>ROWS</th>
                <th>NC (RUNNING)</th>
            </tr>
        </thead>
        <tbody>
            <tr class="sh-start">
                <td>—</td>
                <td class="st-nrt">START</td>
                <td>Opening needle count</td>
                <td>—</td>
                <td class="st-nc">${startN} N</td>
            </tr>
            ${bodyRows}
        </tbody>
        <tfoot>
            <tr>
                <td colspan="2" class="sh-all-label">ALL =</td>
                <td class="sh-all-n" colspan="3">${finalN} N &nbsp;|&nbsp; ROWS USED = ${totalRused} R</td>
            </tr>
        </tfoot>
    </table>`;
}


// ======================================================
// HEADER
// ======================================================

function buildHeader(frm) {
    let style =
        frm.doc.style     ||
        frm.doc.style_no  ||
        frm.doc.item_code ||
        frm.doc.name      || "-";

    let unit     = getGaugeUnit(frm);
    let unitLabel = (unit === "per_cm") ? "per cm" : "per inch";
    let sLabel   = (unit === "per_cm") ? "NPC" : "SPI";
    let rLabel   = (unit === "per_cm") ? "RPC" : "RPI";

    function hc(label, value) {
        return `<td>
            <div class="hc-l">${label}</div>
            <div class="hc-v">${value || "—"}</div>
        </td>`;
    }
    function sc(label, val, codes) {
        let v = parseFloat(val) || 0;
        return `<td>
            <div class="hc-l">${label}</div>
            <div class="hc-v ${v ? "hc-active" : ""}">${v ? v + "%" : "—"}</div>
            <div class="hc-sub">${codes}</div>
        </td>`;
    }

    return `
    <div class="hdr">
        <div class="hdr-band">
            <div class="hdr-title">KNITTING SPECIFICATIONS — TECHNICAL PROGRAM SHEET</div>
            <div class="hdr-sub">
                GAUGE UNIT: <b>${unitLabel}</b> &nbsp;|&nbsp;
                ${sLabel}: <b>${frm.doc.spi || "—"}</b> &nbsp;|&nbsp;
                ${rLabel}: <b>${frm.doc.rpi || "—"}</b> &nbsp;|&nbsp;
                GAUGE: <b>${frm.doc.gauge || "—"}</b>
            </div>
        </div>
        <table class="hdr-tbl">
            <tr>
                ${hc("DATE",        frm.doc.date || new Date().toLocaleDateString())}
                ${hc("STYLE NO",    style)}
                ${hc("BUYER",       frm.doc.buyer)}
                ${hc("SEASON",      frm.doc.season)}
                ${hc("ORDER NO",    frm.doc.order_no || frm.doc.order_number)}
                ${hc("DESCRIPTION", frm.doc.description || frm.doc.item_name)}
                ${hc("MATERIAL",    frm.doc.material || frm.doc.yarn_count)}
                ${hc("PROG",        frm.doc.machine || frm.doc.prog)}
            </tr>
            <tr>
                ${hc("BODY PLY",    frm.doc.body_ply || frm.doc.ply)}
                ${hc("YARN COUNT",  frm.doc.yarn_count)}
                ${sc("CHEST SHR",   frm.doc.chest_shrinkage,  "A1 D1 D2")}
                ${sc("LENGTH SHR",  frm.doc.length_shrinkage, "B1 C1 C2 D4")}
                ${sc("SLEEVE SHR",  frm.doc.sleeve_shrinkage, "C6 C7")}
                ${sc("RIB SHR",     frm.doc.rib_shrinkage,    "L1 L2 C3")}
                <td colspan="2" class="hdr-formula">
                    KNIT CM = FIN CM ÷ (1 − SHR%)<br>
                    ${sLabel === "NPC"
                        ? `N = KNIT CM × ${sLabel} &nbsp; R = KNIT CM × ${rLabel}`
                        : `N = (KNIT CM ÷ 2.54) × ${sLabel} &nbsp; R = (KNIT CM ÷ 2.54) × ${rLabel}`
                    }
                </td>
            </tr>
        </table>
    </div>`;
}


// ======================================================
// SVG HELPERS
// ======================================================

// Horizontal dimension tick line above the shape
function dimH(x1, x2, y, label) {
    let mx = (x1 + x2) / 2;
    return `
    <line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="#333" stroke-width="0.9"/>
    <line x1="${x1}" y1="${y-5}" x2="${x1}" y2="${y+5}" stroke="#333" stroke-width="0.9"/>
    <line x1="${x2}" y1="${y-5}" x2="${x2}" y2="${y+5}" stroke="#333" stroke-width="0.9"/>
    <text x="${mx}" y="${y-7}" text-anchor="middle"
        font-family="Courier New" font-size="9" font-weight="700" fill="#111">${label}</text>`;
}

// Vertical dimension tick line right of shape
function dimV(x, y1, y2, label) {
    let my = (y1 + y2) / 2;
    return `
    <line x1="${x}" y1="${y1}" x2="${x}" y2="${y2}" stroke="#333" stroke-width="0.9"/>
    <line x1="${x-4}" y1="${y1}" x2="${x+4}" y2="${y1}" stroke="#333" stroke-width="0.9"/>
    <line x1="${x-4}" y1="${y2}" x2="${x+4}" y2="${y2}" stroke="#333" stroke-width="0.9"/>
    <text x="${x+10}" y="${my+3}" text-anchor="middle"
        font-family="Courier New" font-size="9" font-weight="700" fill="#111"
        transform="rotate(90,${x+10},${my+3})">${label}</text>`;
}

// Label centred on a zone
function lbl(cx, cy, text, fs) {
    return `<text x="${cx}" y="${cy}" text-anchor="middle"
        font-family="Courier New" font-size="${fs||9}" font-weight="700" fill="#111">${text}</text>`;
}

function sub(cx, cy, text) {
    return `<text x="${cx}" y="${cy}" text-anchor="middle"
        font-family="Courier New" font-size="7.5" fill="#555">${text}</text>`;
}


// ======================================================
// FRONT SVG  (viewBox 0 0 400 500)
// Shape:  x=75–325  y=70–400
// Rib:    y=400–432
// Dims:   top y=20–65,  right x=335–395
// ======================================================

function buildFrontSVG(frm) {
    let A1 = getByCode(frm, "A1");
    let B1 = getByCode(frm, "B1");
    let C2 = getByCode(frm, "C2");
    let D1 = getByCode(frm, "D1");
    let D2 = getByCode(frm, "D2");
    let D4 = getByCode(frm, "D4");
    let L1 = getByCode(frm, "L1");
    let L2 = getByCode(frm, "L2");

    // Armhole line Y = proportional to C2 within body
    // Body height = 330px (y70→y400), C2 occupies the upper portion
    let bodyH   = 330;
    let ahFrac  = R(C2) && R(B1) ? R(C2) / R(B1) : 0.45;
    let ahY     = Math.round(70 + bodyH * (1 - ahFrac));  // armhole from top

    return `<svg viewBox="0 0 400 500" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block;">
        <rect width="400" height="500" fill="#f9f9f9"/>

        <!-- BODY RECT -->
        <rect x="75" y="70" width="250" height="330" fill="white" stroke="#111" stroke-width="2"/>

        <!-- FRONT NECK (U shape) -->
        <path d="M148 70 Q200 118 252 70" fill="#f9f9f9" stroke="#111" stroke-width="1.8"/>

        <!-- ARMHOLE GUIDELINE -->
        <line x1="75" y1="${ahY}" x2="325" y2="${ahY}"
            stroke="#aaa" stroke-width="0.8" stroke-dasharray="5,3"/>

        <!-- RIB BAND -->
        <rect x="75" y="400" width="250" height="32" fill="#e2e2e2" stroke="#111" stroke-width="1.5"/>

        <!-- ── LABELS ── -->
        ${lbl(200, 168, `A1 = ${dv(N(A1))} N`)}
        ${sub(200, 179, `chest  ${f1(K(A1))} cm knit`)}

        ${lbl(200, ahY - 8, `ARMHOLE  ${dv(R(C2))} R`, 8)}

        ${lbl(200, 93, `NK = ${dv(N(D2))}N  DROP = ${dv(R(D4))}R`, 7.5)}

        ${lbl(200, 60, `D1 = ${dv(N(D1))}N  (SHOULDER)`, 8)}

        ${lbl(200, 417, `L1 = ${dv(N(L1))} N   L2 = ${dv(R(L2))} R`)}
        ${sub(200, 429, `rib  ${f1(K(L1))} cm knit`)}

        <!-- ── DIMENSION LINES ── -->
        ${dimH(75, 325, 38, `A1  ${dv(N(A1))}N  /  ${f1(K(A1))}cm`)}
        ${dimH(148, 252, 22, `D1  ${dv(N(D1))}N`)}
        ${dimV(355, 70, 400, `B1  ${dv(R(B1))}R  /  ${f1(K(B1))}cm`)}
        ${dimV(372, ahY, 400, `C2  ${dv(R(C2))}R`)}

        <!-- PANEL TAG -->
        <rect x="75" y="70" width="44" height="14" fill="#111"/>
        <text x="97" y="81" text-anchor="middle" font-family="Courier New"
            font-size="8" font-weight="700" fill="white">FRONT</text>

    </svg>`;
}


