// ======================================================
// MEASUREMENT TABLE
// ======================================================

function buildMeasurementTable(frm) {
    let unit  = getGaugeUnit(frm);
    let sLbl  = unit === "per_cm" ? "NPC" : "SPI";
    let rLbl  = unit === "per_cm" ? "RPC" : "RPI";
    let sVal  = parseFloat(frm.doc.spi) || 0;
    let rVal  = parseFloat(frm.doc.rpi) || 0;

    let rows = getMeasurementRows(frm);
    let html = rows.map(r => {
        let code = (r.code || "").trim().toUpperCase();
        let pct  = getShrinkagePct(frm, code);
        return `<tr>
            <td class="mt-code">${r.code || ""}</td>
            <td class="mt-desc">${r.point_of_measure || ""}</td>
            <td class="mt-n">${f1(P(r))}</td>
            <td class="mt-s">${pct ? pct + "%" : "—"}</td>
            <td class="mt-n mt-k">${f1(K(r))}</td>
            <td class="mt-n mt-nn">${dv(N(r))}</td>
            <td class="mt-n mt-rr">${dv(R(r))}</td>
        </tr>`;
    }).join("");

    return `
    <div class="mt-gauge-bar">
        ${sLbl} = ${sVal || "—"} &nbsp;|&nbsp;
        ${rLbl} = ${rVal || "—"} &nbsp;|&nbsp;
        UNIT: ${unit === "per_cm" ? "per cm" : "per inch"}
    </div>
    <table class="mt">
        <thead><tr>
            <th>CODE</th><th>MEASUREMENT</th>
            <th>FIN CM</th><th>SHR%</th><th>KNIT CM</th>
            <th>N</th><th>R</th>
        </tr></thead>
        <tbody>${html}</tbody>
    </table>`;
}


// ======================================================
// PROGRAMMER INSTRUCTIONS
// ======================================================

function buildPrograms(frm) {
    let A1 = getByCode(frm, "A1");
    let B1 = getByCode(frm, "B1");
    let C1 = getByCode(frm, "C1");
    let C2 = getByCode(frm, "C2");
    let C3 = getByCode(frm, "C3");
    let C5 = getByCode(frm, "C5");
    let C7 = getByCode(frm, "C7");
    let D1 = getByCode(frm, "D1");
    let D2 = getByCode(frm, "D2");
    let D4 = getByCode(frm, "D4");
    let L1 = getByCode(frm, "L1");
    let L2 = getByCode(frm, "L2");

    let chestN    = N(A1);
    let shoulderN = N(D1) || Math.round(chestN * 0.60);
    let armSteps  = calcShaping(chestN, shoulderN, R(C2), "dec");

    let bicepN    = N(C7);
    let cuffN     = N(C3);
    let taperR    = Math.max(R(C1) - R(C5), 0);
    let tapSteps  = calcShaping(cuffN, bicepN, taperR, "inc");

    let neckN     = N(D2);
    let centreN   = Math.round(neckN / 3 / 2) * 2;
    let sideN     = Math.round((neckN - centreN) / 2);
    let neckSteps = calcShaping(sideN, 0, R(D4), "dec");

    function block(num, title, infoHTML, tableHTML) {
        return `<div class="pg-block">
            <div class="pg-title">${num}. ${title}</div>
            <div class="pg-info">${infoHTML}</div>
            ${tableHTML}
        </div>`;
    }

    // ── BODY SEQUENCE ──────────────────────────────────
    let bodyBlock = `<div class="pg-block">
        <div class="pg-title">1. BODY KNITTING SEQUENCE</div>
        <table class="seq-tbl">
            <tr>
                <td class="sq-num">1</td>
                <td>Cast on <b>${dv(N(L1))}</b> N
                    <span class="sq-note">(L1 = ${f1(K(L1))} cm knit)</span>
                </td>
            </tr>
            <tr>
                <td class="sq-num">2</td>
                <td>Knit rib <b>${dv(R(L2))}</b> R
                    <span class="sq-note">(L2 = ${f1(K(L2 ? getByCode(frm,"L2") : {}))} cm knit)</span>
                </td>
            </tr>
            <tr>
                <td class="sq-num">3</td>
                <td>Change cam → body tension</td>
            </tr>
            <tr>
                <td class="sq-num">4</td>
                <td>Expand to <b>${dv(N(A1))}</b> N
                    <span class="sq-note">(A1 chest = ${f1(K(A1))} cm knit)</span>
                </td>
            </tr>
            <tr>
                <td class="sq-num">5</td>
                <td>Knit body <b>${dv(R(B1))}</b> R
                    <span class="sq-note">(B1 length = ${f1(K(B1))} cm knit)</span>
                </td>
            </tr>
            <tr>
                <td class="sq-num">6</td>
                <td>Begin armhole shaping → see Program 2</td>
            </tr>
        </table>
    </div>`;

    // ── ARMHOLE ────────────────────────────────────────
    let armInfo = `
    <table class="pi-tbl"><tr>
        <td class="pi-l">CHEST</td><td class="pi-v">${dv(chestN)}</td><td class="pi-u">N</td>
        <td class="pi-l">SHOULDER</td><td class="pi-v">${dv(shoulderN)}</td><td class="pi-u">N</td>
        <td class="pi-l">REDUCE TOTAL</td><td class="pi-v">${dv(chestN-shoulderN)}</td><td class="pi-u">N</td>
        <td class="pi-l">PER SIDE</td><td class="pi-v">${dv(Math.round((chestN-shoulderN)/2))}</td><td class="pi-u">N</td>
        <td class="pi-l">OVER</td><td class="pi-v">${dv(R(C2))}</td><td class="pi-u">R</td>
    </tr></table>`;

    // ── SLEEVE TAPER ───────────────────────────────────
    let tapInfo = `
    <table class="pi-tbl"><tr>
        <td class="pi-l">CUFF</td><td class="pi-v">${dv(cuffN)}</td><td class="pi-u">N</td>
        <td class="pi-l">BICEP</td><td class="pi-v">${dv(bicepN)}</td><td class="pi-u">N</td>
        <td class="pi-l">INC TOTAL</td><td class="pi-v">${dv(bicepN-cuffN)}</td><td class="pi-u">N</td>
        <td class="pi-l">PER SIDE</td><td class="pi-v">${dv(Math.round((bicepN-cuffN)/2))}</td><td class="pi-u">N</td>
        <td class="pi-l">TAPER R</td><td class="pi-v">${dv(taperR)}</td><td class="pi-u">R</td>
    </tr></table>`;

    // ── NECK ───────────────────────────────────────────
    let nkInfo = `
    <table class="pi-tbl"><tr>
        <td class="pi-l">NECK WIDTH</td><td class="pi-v">${dv(neckN)}</td><td class="pi-u">N</td>
        <td class="pi-l">CENTRE C/O</td><td class="pi-v">${dv(centreN)}</td><td class="pi-u">N</td>
        <td class="pi-l">EACH SIDE</td><td class="pi-v">${dv(sideN)}</td><td class="pi-u">N</td>
        <td class="pi-l">DROP</td><td class="pi-v">${dv(R(D4))}</td><td class="pi-u">R</td>
    </tr></table>`;

    return `<div class="prog-wrap">
        <div class="nrt-legend">
            N-R-T KEY: &nbsp;
            <b>N</b> = needles each end &nbsp;|&nbsp;
            <b>R</b> = row interval &nbsp;|&nbsp;
            <b>T</b> = times repeated &nbsp;|&nbsp;
            <b>NC</b> = cumulative needle count after step
        </div>
        ${bodyBlock}
        ${block("2", "ARMHOLE SHAPING  (each side simultaneously)", armInfo, shimaTable(armSteps, chestN, "dec"))}
        ${block("3", "SLEEVE TAPER  (each side simultaneously)",    tapInfo, shimaTable(tapSteps, cuffN, "inc"))}
        ${block("4", "NECK SHAPING  (each side after centre cast-off)", nkInfo, shimaTable(neckSteps, sideN, "dec"))}
    </div>`;
}


