frappe.ui.form.on('Daily Sample Request', {
	refresh: function(frm) {

		// Actions ড্রপডাউনে "VIEW ORDER SHEET" অপশন - এটি Order Sheet Entry তে নিয়ে যাবে
		frm.page.add_action_item(__('VIEW ORDER SHEET'), function() {
			navigateToOrderSheet(frm);
		});

		// টুলবারে "ORDER SHEET" বাটন - একই কাজ করবে, সরাসরি দেখা যাবে
		frm.add_custom_button(__('ORDER SHEET'), function() {
			navigateToOrderSheet(frm);
		});

		function navigateToOrderSheet(frm) {
			// DSR নাম থেকে Sample Type প্রিফিক্স সরিয়ে Buyer-Style বের করা হচ্ছে
			// যেমন: FIT SAMPLE-PEPCO-SS27LO243-... → PEPCO-SS27LO243
			let name = frm.doc.name;

			let sampleTypes = [
				'DEVELOPMENT SAMPLE', 'FIT SAMPLE', 'SIZE SET SAMPLE', 'PHOTO SAMPLE',
				'SALESMAN SAMPLE (SMS)', 'YARN DYED SAMPLE', 'WASH/FINISH APPROVAL SAMPLE',
				'PRE-PRODUCTION SAMPLE (PPS)', 'TOP OF PRODUCTION (TOP) SAMPLE',
				'COUNTER SAMPLE', 'SHIPMENT SAMPLE', 'DUPLICATE / ARCHIVE SAMPLE', 'MARKETING SAMPLE'
			];

			let stripped = name;
			sampleTypes.forEach(type => {
				if (name.startsWith(type + '-')) {
					stripped = name.slice(type.length + 1);
				}
			});

			// প্রথম দুইটি সেগমেন্ট নিয়ে Buyer-Style কী তৈরি করা হচ্ছে
			let parts = stripped.split('-');
			let buyerStyle = parts[0] + '-' + parts[1];

			// Order Sheet Entry তে Buyer-Style দিয়ে খোঁজা হচ্ছে
			frappe.db.get_list('Order Sheet Entry', {
				filters: [
					['name', 'like', `%${buyerStyle}%`]
				],
				fields: ['name'],
				limit: 1
			}).then(results => {
				if (results && results.length > 0) {
					frappe.set_route('Form', 'Order Sheet Entry', results[0].name);
				} else {
					frappe.msgprint({
						title: __('Not Found'),
						indicator: 'red',
						message: __('No Order Sheet Entry found for this Sample Request.')
					});
				}
			});
		}
	}
});

frappe.ui.form.on("Order Sheet Entry", {

