});


// =====================================================
// BUTTON (ALWAYS SAFE)
// =====================================================

function add_sample_button(frm) {
	frm.remove_custom_button("SAMPLE REQ.");

	frm.add_custom_button("SAMPLE REQ.", function () {
		open_glass_modal(frm);
	});
}


// =====================================================
// GLASSMORPHIC MODAL (PRO UI)
// =====================================================

function open_glass_modal(frm) {

	let filters = {};

	if (frm.doc.style_name) filters.style = frm.doc.style_name;
	if (frm.doc.buyer) filters.buyer = frm.doc.buyer;
	if (frm.doc.season) filters.season_collection = frm.doc.season;
	if (frm.doc.gauge) filters.gauge = frm.doc.gauge;

	frappe.db.get_list("Daily Sample Request", {
		filters: filters,
		fields: ["name", "sample_type", "style", "buyer", "season_collection"],
		limit: 100
	}).then(r => {

		let data = r || [];

		if (!data.length) {
			frappe.msgprint("No Matching Sample Requests Found");
			return;
		}

		render_glass_ui(frm, data);

	});

}


// =====================================================
// GLASS UI RENDER (FIBONACCI SPACING SYSTEM)
// =====================================================

function render_glass_ui(frm, data) {

	let html = `
	<div style="
		position:relative;
		padding:18px;
		font-family: Inter, sans-serif;
	">

		<!-- GLASS CONTAINER -->
		<div style="
			background: rgba(255,255,255,0.65);
			backdrop-filter: blur(18px);
			-webkit-backdrop-filter: blur(18px);
			border: 1px solid rgba(255,255,255,0.3);
			border-radius: 18px;
			box-shadow: 0 20px 60px rgba(0,0,0,0.15);
			padding: 18px;
		">

			<!-- SEARCH -->
			<input id="glassSearch"
				placeholder="Search sample request..."
				style="
					width:100%;
					padding:14px 16px;
					border-radius:12px;
					border:1px solid rgba(0,0,0,0.08);
					font-size:13px;
					outline:none;
					margin-bottom:14px;
				"/>

			<!-- GRID -->
			<div id="glassGrid"
				style="
					display:flex;
					flex-direction:column;
					gap:10px;
					max-height:420px;
					overflow-y:auto;
					overflow-x:hidden;
					padding-right:4px;
				">
	`;

	data.forEach(d => {

		html += `
			<div class="glass-card"
				data-text="${(d.name + d.sample_type + d.style + d.buyer).toLowerCase()}"

				onclick="open_sample('${d.name}')"

				style="
					padding:14px;
					border-radius:14px;
					background: rgba(255,255,255,0.7);
					border:1px solid rgba(0,0,0,0.06);
					cursor:pointer;
					transition: all 0.25s ease;
				"
				onmouseover="this.style.transform='translateY(-2px)'"
				onmouseout="this.style.transform='translateY(0)'"
			>

				<div style="
					font-size:14px;
					font-weight:600;
					letter-spacing:0.2px;
				">
					${d.sample_type || "SAMPLE"} • ${d.name}
				</div>

				<div style="
					font-size:12px;
					color:#6b7280;
					margin-top:6px;
				">
					${d.style || ""} • ${d.buyer || ""} • ${d.season_collection || ""}
				</div>

			</div>
		`;

	});

	html += `
			</div>
		</div>
	</div>
	`;


	let dialog = new frappe.ui.Dialog({
		title: "Select Sample Request",
		size: "large",
		fields: [{ fieldtype: "HTML", fieldname: "html" }]
	});

	dialog.fields_dict.html.$wrapper.html(html);
	dialog.show();


	// GLOBAL OPEN
	window.open_sample = function (name) {

		frm.set_value("sample_request", name);

		frappe.set_route("Form", "Daily Sample Request", name);

		sync_comments(frm);

		dialog.hide();

	};


	// =====================================================
	// SEARCH (FIXED + SMOOTH + NO LAG)
	// =====================================================

	setTimeout(() => {

		let input = document.getElementById("glassSearch");

		let timeout;

		input.addEventListener("input", function () {

			clearTimeout(timeout);

			timeout = setTimeout(() => {

				let val = this.value.toLowerCase();

				document.querySelectorAll(".glass-card").forEach(el => {

					let text = el.getAttribute("data-text");

					el.style.display = text.includes(val) ? "block" : "none";

				});

			}, 80);

		});

	}, 200);

}


// =====================================================
// COMMENTS SYNC (UNCHANGED LOGIC)
// =====================================================

function sync_comments(frm) {

	if (!frm.doc.sample_request) return;

	if (frm.__synced === frm.doc.sample_request) return;

	frm.__synced = frm.doc.sample_request;

	frappe.call({
		method: "frappe.client.get",
		args: {
			doctype: "Daily Sample Request",
			name: frm.doc.sample_request
		},
		callback(r) {

			if (!r.message) return;

			frm.clear_table("available_comments");

			(r.message.available_comments || []).forEach(row => {

				let c = frm.add_child("available_comments");

				c.daily_sample_request = r.message.name;
				c.date = row.date;
				c.comments_name = row.comments_name;
				c.comments_file = row.comments_file;

			});

			frm.refresh_field("available_comments");

		}
	});

}

