    }

});






function calculate_costing(frm) {

    //--------------------------------
    // ইয়ার্ন (সুতা) হিসাব
    // সূত্র: গ্রস ওজন = নেট ওজন × (১ + অপচয়%)
    //        কনজাম্পশন = গ্রস ওজন ÷ ১০০০ (কেজিতে রূপান্তর)
    //        ইয়ার্ন খরচ = কনজাম্পশন × ২.২০৪৬২ (পাউন্ডে রূপান্তর) × দর/পাউন্ড
    //--------------------------------

    let yarn_total = 0; // মোট ইয়ার্ন খরচ

    (frm.doc.table_qhiz || []).forEach(row => {

        // নেট ওজন (গ্রামে)
        let net = flt(row.net_weight_gm);

        // অপচয় শতাংশ
        let wastage = flt(row.wastage);

        // ইয়ার্নের দর প্রতি পাউন্ড
        let rate_lb = flt(row.yarn_rate_lb);

        // গ্রস ওজন = নেট ওজন × (১ + অপচয়/১০০)
        let gross_weight = net * (1 + (wastage / 100));

        // কনজাম্পশন কেজিতে (গ্রাম ÷ ১০০০)
        let consumption = gross_weight / 1000;

        // ইয়ার্ন খরচ: কেজি → পাউন্ড (×২.২০৪৬২) তারপর দর গুণ
        let yarn_cost = (consumption * 2.20462) * rate_lb;

        // সারিতে গণনা করা মান সেট করো
        row.gross_weight = gross_weight;
        row.consumption = consumption;
        row.yarn_cost = yarn_cost;

        // মোট ইয়ার্ন খরচে যোগ করো
        yarn_total += yarn_cost;

    });




    //--------------------------------
    // ট্রিমস হিসাব
    // সূত্র: পরিমাণ (amount) = পরিমাণ (qty) × দর (rate)
    //--------------------------------

    let trims = 0; // মোট ট্রিমস খরচ

    (frm.doc.table_frlo || []).forEach(row => {

        // পরিমাণ = qty × rate
        let amount = flt(row.qty) * flt(row.rate);

        row.amount = amount;

        // মোট ট্রিমস খরচে যোগ করো
        trims += amount;

    });




    //--------------------------------
    // মোট মালামাল খরচ
    // সূত্র: material = ইয়ার্ন + ট্রিমস
    //--------------------------------

    let material = yarn_total + trims;




    //--------------------------------
    // ম্যানুফ্যাকচারিং (উৎপাদন) খরচ
    // সূত্র: সব উৎপাদন ধাপের খরচের যোগফল
    //--------------------------------

    let manufacturing = 0; // মোট উৎপাদন খরচ

    (frm.doc.table_fxhi || []).forEach(row => {

        manufacturing +=
            flt(row.knitting)   // নিটিং
            + flt(row.linking)  // লিংকিং
            + flt(row.mending)  // মেন্ডিং
            + flt(row.sewing)   // সেলাই
            + flt(row.washing)  // ওয়াশিং
            + flt(row.ironing)  // আয়রনিং
            + flt(row.packing); // প্যাকিং

    });




    //--------------------------------
    // ওভারহেড (উপরিব্যয়) হিসাব
    // পদ্ধতি ১ - শতাংশ: (material + manufacturing) × overhead%
    // পদ্ধতি ২ - নির্দিষ্ট পরিমাণ: সরাসরি fixed amount
    //--------------------------------

    let overhead = 0; // মোট ওভারহেড

    if (frm.doc.overhead_method === "Percentage") {

        // শতাংশ পদ্ধতি: মালামাল ও উৎপাদন খরচের উপর শতাংশ হিসাবে
        overhead =
            (material + manufacturing)
            * (flt(frm.doc.overhead_percentage) / 100);

    } else {

        // নির্দিষ্ট পরিমাণ পদ্ধতি: ফর্মে দেওয়া নির্দিষ্ট ওভারহেড
        overhead = flt(frm.doc.overhead_fixed_amount);

    }




    //--------------------------------
    // কমার্শিয়াল খরচ হিসাব
    // ⚠️ বাগ সংশোধন: আগে শুধু (material + manufacturing + overhead) এর উপর
    //    শতাংশ ধরা হতো। সঠিক FOB-এর জন্য এটাই ঠিক আছে কারণ profit এখনো
    //    যোগ হয়নি এই ধাপে।
    // সূত্র: commercial = (material + manufacturing + overhead) × commercial%
    //--------------------------------

    let subtotal_before_commercial = material + manufacturing + overhead;

    let commercial =
        subtotal_before_commercial
        * (flt(frm.doc.commercial_cost) / 100);




    //--------------------------------
    // মুনাফা (Profit) হিসাব
    // ⚠️ বাগ সংশোধন: profit সাধারণত FOB-এর উপর % হিসাবে ধরা হয়।
    //    কিন্তু FOB নির্ভর করে profit-এর উপর — এটা circular।
    //    সঠিক পদ্ধতি: profit% কে (১ - profit%) দিয়ে ভাগ করে
    //    বেস কস্টের উপর প্রয়োগ করতে হয়।
    //
    //    অর্থাৎ: যদি FOB-এর উপর profit% চাই, তাহলে —
    //    profit = base_cost × (profit% / (100 - profit%))
    //
    //    যেখানে base_cost = material + manufacturing + overhead + commercial
    //--------------------------------

    let base_cost = material + manufacturing + overhead + commercial;

    let profit_pct = flt(frm.doc.target_profit);

    // FOB-এর উপর % ধরে সঠিক মুনাফা হিসাব
    // উদাহরণ: FOB-এর ২০% মুনাফা চাইলে → profit = base × (20/80)
    let profit =
        profit_pct > 0 && profit_pct < 100
            ? base_cost * (profit_pct / (100 - profit_pct))
            : 0;




    //--------------------------------
    // FOB মূল্য হিসাব
    // সূত্র: FOB = material + manufacturing + overhead + commercial + profit
    // যাচাই: profit ÷ FOB × ১০০ = target_profit% (সঠিক হওয়া উচিত)
    //--------------------------------

    let fob = base_cost + profit;




    //--------------------------------
    // UI আপডেট করো
    //--------------------------------

    // ইয়ার্ন ও ট্রিমস টেবিল রিফ্রেশ করো
    frm.refresh_field("table_qhiz");
    frm.refresh_field("table_frlo");

    // মালামাল খরচ সেট করো
    frm.set_value("material_cost", material.toFixed(2));

    // উৎপাদন খরচ সেট করো
    frm.set_value("manufacturing_cost", manufacturing.toFixed(2));

    // ওভারহেড পরিমাণ সেট করো (দুটো ফিল্ডে)
    frm.set_value("overhead_amount", overhead.toFixed(2));
    frm.set_value("overhead_cost", overhead.toFixed(2));

    // কমার্শিয়াল খরচ সেট করো
    frm.set_value("total_commercial_cost", commercial.toFixed(2));

    // মুনাফার পরিমাণ সেট করো
    frm.set_value("profit_amount", profit.toFixed(2));

    // চূড়ান্ত FOB মূল্য সেট করো
    frm.set_value("fob_price", fob.toFixed(2));

}

