        calculate_yarn(frm);
    }
});

frappe.ui.form.on('Yarn Details', {
    price: function(frm) {
        calculate_yarn(frm);
    },

    yarn_details_add: function(frm) {
        calculate_yarn(frm);
    },

    yarn_details_remove: function(frm) {
        calculate_yarn(frm);
    }
});

function calculate_yarn(frm) {

    // Calculate Balance Yarn
    let total_required = flt(frm.doc.total_required_yarn);
    let total_received = flt(frm.doc.total_receive_yarn);

    let balance_yarn = total_required - total_received;

    frm.set_value('total_balance_yarn', balance_yarn);

    // Get Price from First Yarn Details Row
    let yarn_price = 0;

    if (frm.doc.yarn_details && frm.doc.yarn_details.length > 0) {
        yarn_price = flt(frm.doc.yarn_details[0].price);
    }

    // Calculate Total Yarn Value
    let total_yarn_value = total_required * yarn_price;

    frm.set_value('total_yarn_value', total_yarn_value);
}

frappe.ui.form.on('Order Sheet Entry', {

    refresh(frm) {
        calculate_colour_yarn(frm);
    },

    total_required_yarn(frm) {
        calculate_colour_yarn(frm);
    },

    multiple_colour_ratio_add(frm, cdt, cdn) {
        calculate_colour_yarn(frm);
    },

    multiple_colour_ratio_remove(frm, cdt, cdn) {
        calculate_colour_yarn(frm);
    }
});


frappe.ui.form.on('Multiple Colour Ratio', {

    weight(frm, cdt, cdn) {
        calculate_colour_yarn(frm);
    }
});


function calculate_colour_yarn(frm) {

    const rows = frm.doc.multiple_colour_ratio || [];

    if (!rows.length) {
        return;
    }

    // ------------------------------------------
    // TOTAL DYEING ORDER / TOTAL COLOUR WEIGHT
    // ------------------------------------------

    let total_weight = 0;

    rows.forEach(row => {
        total_weight += flt(row.weight);
    });


    // ------------------------------------------
    // TOTAL REQUIRED YARN
    // Already includes 10% wastage
    // ------------------------------------------

    const total_yarn = flt(frm.doc.total_required_yarn);


    // ------------------------------------------
    // If no weight or yarn, clear calculations
    // ------------------------------------------

    if (total_weight <= 0 || total_yarn <= 0) {

        rows.forEach(row => {

            frappe.model.set_value(
                row.doctype,
                row.name,
                'percentage',
                0
            );

            frappe.model.set_value(
                row.doctype,
                row.name,
                'total_qty',
                0
            );

        });

        return;
    }


    // ------------------------------------------
    // CALCULATE EACH COLOUR
    // ------------------------------------------

    let calculated_yarn = 0;

    rows.forEach((row, index) => {

        const weight = flt(row.weight);

        // Colour percentage
        const percentage =
            (weight / total_weight) * 100;

        // Colour-wise yarn
        let colour_yarn =
            total_yarn * (weight / total_weight);


        // --------------------------------------
        // Last row gets the rounding balance
        // so total always equals Total Required Yarn
        // --------------------------------------

        if (index === rows.length - 1) {
            colour_yarn = total_yarn - calculated_yarn;
        }


        calculated_yarn += colour_yarn;


        // Percentage
        frappe.model.set_value(
            row.doctype,
            row.name,
            'percentage',
            percentage
        );


        // Colour-wise Yarn Required
        frappe.model.set_value(
            row.doctype,
            row.name,
            'total_qty',
            colour_yarn
        );

    });


    frm.refresh_field('multiple_colour_ratio');
}

