    po_qty(frm, cdt, cdn) {
        calculate_total_po_qty(frm);
    }
});

function calculate_total_po_qty(frm) {
    let total = 0;

    (frm.doc.order_sheet_po_details || []).forEach(row => {
        total += flt(row.po_qty);
    });

    frm.set_value('total_po_qty', total);
}

frappe.ui.form.on('Order Sheet Entry', {
    refresh(frm) {
        calculate_days(frm);
    },

    shipment_date(frm) {
        calculate_days(frm);
    }
});

function calculate_days(frm) {
    if (frm.doc.shipment_date) {
        let today = frappe.datetime.get_today();
        let days = frappe.datetime.get_diff(frm.doc.shipment_date, today);
        frm.set_value('days_remaining', days);
    } else {
        frm.set_value('days_remaining', null);
    }
}
